import com.prometheus.clq.model.Question

object QuestionsExpansion19 {
    fun get(): List<Question> = listOf(
        Question(12000, "Quel curler canadien a remporté 38 championnats mondiaux?", listOf("Kevin Martin", "Randy Ferbey", "Russ Howard", "Ed Werenich"), 0, "Sport", Difficulty.HARD, explanation = "Kevin Martin, surnommé « The Old Bear », est considéré comme l'un des plus grands curleurs de l'histoire. Il a accumulé 38 titres de champion du monde, un record inégalé dans ce sport."),
        Question(12001, "En cricket, combien de balles constituent un over?", listOf("4", "6", "8", "10"), 1, "Sport", Difficulty.MEDIUM, explanation = "Un over au cricket est traditionnellement composé de six lancers valides, une règle standardisée depuis le XIXe siècle pour équilibrer le jeu entre batteurs et lanceurs."),
        Question(12002, "Le biathlon combine le ski de fond et quel autre sport?", listOf("Patinage", "Tir à la carabine", "Saut à ski", "Bobsleigh"), 1, "Sport", Difficulty.EASY, explanation = "Le biathlon est un sport d'hiver qui alterne des tours de ski de fond et des séances de tir à la carabine, où les athlètes doivent viser des cibles à distance."),
        Question(12003, "Quel est le nom du gymnaste suisse qui a inventé le trampoline moderne?", listOf("Jakob Tullin", "George Nissen", "Walter Schindelé", "Hans Reusch"), 1, "Sport", Difficulty.HARD, explanation = "George Nissen, un gymnaste américain (et non suisse), a inventé le trampoline moderne dans les années 1930 en s'inspirant des filets de sécurité des trapézistes."),
        Question(12004, "En polo, combien de joueurs constituent une équipe?", listOf("3", "4", "5", "6"), 1, "Sport", Difficulty.MEDIUM, explanation = "Au polo, chaque équipe est composée de quatre joueurs à cheval, une règle standardisée au XIXe siècle pour équilibrer vitesse et stratégie sur le terrain."),
        Question(12005, "Le sport appelé 'Hurling' est originaire de quel pays?", listOf("Écosse", "Irlande", "Pays de Galles", "Cornouailles"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le hurling est un sport traditionnel irlandais, pratiqué depuis des siècles, souvent considéré comme l'un des jeux les plus rapides au monde."),
        Question(12006, "Quel escaladeur français a été le premier à atteindre le sommet du Mont-Blanc avec un certificat officiel?", listOf("Gaston Rébuffat", "Pierre Labric", "Jacques Charignon", "Édouard-Alfred Martel"), 2, "Sport", Difficulty.HARD, explanation = "Jacques Charignon, guide de haute montagne, a réalisé cette ascension officielle en 1786, marquant une première dans l'histoire de l'alpinisme."),
        Question(12007, "Le curl olympique utilise une pierre dont le poids minimum est?", listOf("17 kg", "20 kg", "19.96 kg", "22 kg"), 2, "Sport", Difficulty.HARD, explanation = "Au curling olympique, chaque pierre doit peser au minimum 19,96 kg (44 livres), un standard établi par la Fédération mondiale de curling pour garantir l'équité entre les compétiteurs."),
        Question(12008, "En badminton, quel est le diamètre maximal du volant?", listOf("15 mm", "17 mm", "20 mm", "24 mm"), 3, "Sport", Difficulty.HARD, explanation = "Le volant de badminton doit avoir un diamètre maximal de 24 mm selon les règles de la Fédération mondiale de badminton, afin de garantir des caractéristiques de vol standardisées."),
        Question(12009, "Le squash professionnel se joue sur un court mesurant combien de mètres de long?", listOf("9 m", "9.75 m", "10 m", "11 m"), 1, "Sport", Difficulty.HARD, explanation = "Les dimensions officielles d'un court de squash sont de 9,75 mètres de long sur 6,4 mètres de large, selon les règles de la Fédération mondiale de squash."),
        Question(12010, "Quel sport de raquette se joue en quatre contre quatre?", listOf("Padel", "Pickleball", "Pelote basque", "Frontenis"), 2, "Sport", Difficulty.HARD, explanation = "La pelote basque se pratique en équipes de quatre joueurs dans sa spécialité appelée \"main nue\" ou \"paleta\", où deux équipes de deux joueurs s'affrontent, mais certaines variantes comme le \"joko garbi\" se jouent en quatre contre quatre."),
        Question(12011, "En skateboard, quel est le nom du virage à 360°?", listOf("Kickflip", "Ollie", "Shove-it", "Manual"), 0, "Sport", Difficulty.MEDIUM, explanation = "Un kickflip est un trick de skateboard où la planche effectue une rotation de 360° sur son axe longitudinal, mais il ne s'agit pas d'un virage. Le virage à 360° s'appelle un 360 ollie ou simplement un 360."),
        Question(12012, "Le Kabaddi est un sport collectif originaire de quel continent?", listOf("Afrique", "Asie", "Océanie", "Amérique du Sud"), 1, "Sport", Difficulty.HARD, explanation = "Le Kabaddi est originaire du sous-continent indien, en Asie, où il est pratiqué depuis des millénaires et reste très populaire notamment en Inde et au Bangladesh."),
        Question(12013, "Combien de tentatives a un grimpeur en escalade sportive au niveau des Jeux Olympiques?", listOf("Une", "Deux", "Trois", "Quatre"), 2, "Sport", Difficulty.HARD, explanation = "Aux Jeux Olympiques, chaque grimpeur dispose de trois tentatives pour réaliser la meilleure performance possible sur les voies de difficulté et de bloc."),
        Question(12014, "Le lancer du poids masculin utilise une sphère pesant?", listOf("6 kg", "7.26 kg", "8 kg", "9 kg"), 1, "Sport", Difficulty.HARD, explanation = "Le lancer du poids masculin est une discipline d'athlétisme où la sphère métallique pèse 7,26 kg (16 livres), un standard établi par la fédération internationale."),
        Question(12015, "En athlétisme, quelle distance est le 'steeple chase'?", listOf("3000 m", "3500 m", "2500 m", "4000 m"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le steeple-chase est une épreuve d’athlétisme sur piste de 3000 mètres, comportant des haies et une rivière."),
        Question(12016, "Le record de hauteur en saut en hauteur approche?", listOf("2.30 m", "2.38 m", "2.45 m", "2.50 m"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le record du monde masculin de saut en hauteur est détenu par le Cubain Javier Sotomayor avec 2,45 mètres, établi en 1993. La barre des 2,38 mètres est une performance de très haut niveau, approchant ce record historique."),
        Question(12017, "Quel sport utilise des épées avec des lames de plus de 90 cm?", listOf("Fleuret", "Sabre", "Épée", "Escrime historique"), 2, "Sport", Difficulty.EASY, explanation = "L'épée est une discipline d'escrime dont la lame mesure 90 cm pour un poids maximum de 770 g, soit la plus longue et la plus lourde des trois armes."),
        Question(12018, "Le jeu de paume français se joue sur un terrain de quel nom?", listOf("Court", "Trinquet", "Fronton", "Parc"), 1, "Sport", Difficulty.HARD, explanation = "Le jeu de paume français se pratique dans un trinquet, un terrain fermé par des murs contre lesquels la balle peut rebondir, spécifique à ce sport."),
        Question(12019, "Combien de gants utilise un boxeur lors d'un combat?", listOf("Un", "Deux", "Trois", "Quatre"), 1, "Sport", Difficulty.EASY, explanation = "Un boxeur porte une paire de gants, soit un pour chaque main, afin de se protéger et de protéger son adversaire lors des frappes."),
        Question(12020, "La molécule de l'ADN a été découverte en?", listOf("1945", "1950", "1953", "1960"), 2, "Science", Difficulty.MEDIUM, explanation = "La structure en double hélice de l'ADN a été identifiée par Watson et Crick en 1953."),
        Question(12021, "Quel chimiste a reçu deux prix Nobel dans des domaines différents?", listOf("Linus Pauling", "Marie Curie", "Frederick Sanger", "John Bardeen"), 1, "Science", Difficulty.HARD, explanation = "Marie Curie a reçu le prix Nobel de physique en 1903 pour ses travaux sur la radioactivité, puis celui de chimie en 1911 pour la découverte du radium et du polonium."),
        Question(12022, "L'expérience de la double fente a révélé quel phénomène?", listOf("Réfraction", "Dualité onde-corpuscule", "Polarisation", "Diffraction"), 1, "Science", Difficulty.HARD, explanation = "L'expérience de la double fente montre que les particules, comme les électrons, se comportent à la fois comme des ondes et des particules, un principe clé de la mécanique quantique."),
        Question(12023, "Le nombre d'Avogadro est approximativement?", listOf("6.02 × 10²¹", "6.02 × 10²³", "6.02 × 10²⁵", "6.02 × 10¹⁸"), 1, "Science", Difficulty.MEDIUM, explanation = "Le nombre d'Avogadro représente le nombre d'entités (atomes, molécules) dans une mole d'une substance, soit environ 6,022 × 10²³, une constante fondamentale en chimie."),
        Question(12024, "Quel élément chimique porte le numéro atomique 79?", listOf("Argent", "Platine", "Or", "Mercure"), 2, "Science", Difficulty.EASY, explanation = "L'élément de numéro atomique 79 est l'or, un métal précieux utilisé en bijouterie et en électronique pour sa conductivité et sa résistance à la corrosion."),
        Question(12025, "La vitesse de la lumière dans le vide est?", listOf("300 000 km/s", "299 792 km/s", "350 000 km/s", "250 000 km/s"), 1, "Science", Difficulty.MEDIUM, explanation = "La vitesse de la lumière dans le vide est une constante fondamentale de la physique, notée c, et vaut exactement 299 792 458 mètres par seconde depuis sa redéfinition en 1983."),
        Question(12026, "Quel scientifique a formulé la loi de la gravitation universelle?", listOf("Galilée", "Copernic", "Newton", "Kepler"), 2, "Science", Difficulty.EASY, explanation = "Isaac Newton a formulé la loi de la gravitation universelle en 1687 dans son ouvrage Philosophiæ Naturalis Principia Mathematica, expliquant l'attraction entre les corps massifs."),
        Question(12027, "La théorie de la relativité restreinte a été publiée en?", listOf("1900", "1905", "1915", "1925"), 1, "Science", Difficulty.MEDIUM, explanation = "Albert Einstein publie sa théorie de la relativité restreinte en 1905, dans son article Sur l'électrodynamique des corps en mouvement. Cette année est surnommée son annus mirabilis."),
        Question(12028, "Le boson de Higgs a été découvert au?", listOf("Fermilab", "CERN", "SLAC", "Brookhaven"), 1, "Science", Difficulty.HARD, explanation = "Le boson de Higgs a été observé pour la première fois en 2012 grâce aux collisions de particules réalisées dans le Grand collisionneur de hadrons (LHC) du CERN, situé près de Genève."),
        Question(12029, "Quel gaz noble a été découvert le premier?", listOf("Hélium", "Néon", "Argon", "Radon"), 0, "Science", Difficulty.MEDIUM, explanation = "L'hélium a été identifié en 1868 lors d'une éclipse solaire, avant d'être isolé sur Terre en 1895, ce qui en fait le premier gaz noble découvert."),
        Question(12030, "La photosynthèse produit quel gaz comme déchet?", listOf("Azote", "Monoxyde de carbone", "Oxygène", "Dioxyde de carbone"), 2, "Science", Difficulty.EASY, explanation = "La photosynthèse utilise le dioxyde de carbone et l'eau pour produire du glucose, libérant de l'oxygène comme sous-produit gazeux."),
        Question(12031, "Quel est le point de fusion du tungstène?", listOf("2500°C", "3200°C", "3422°C", "4000°C"), 2, "Science", Difficulty.HARD, explanation = "Le tungstène possède le point de fusion le plus élevé de tous les métaux, atteignant 3422°C, ce qui le rend idéal pour les filaments d'ampoules et les applications à haute température."),
        Question(12032, "Le paradoxe EPR a été proposé par?", listOf("Einstein, Bohr, Rosen", "Einstein, Podolsky, Rosen", "Heisenberg, Einstein, Dirac", "Schrödinger, Einstein, Planck"), 1, "Science", Difficulty.HARD, explanation = "Le paradoxe EPR tire son nom des initiales de ses trois auteurs : Albert Einstein, Boris Podolsky et Nathan Rosen, qui l'ont formulé en 1935 pour critiquer l'interprétation de la mécanique quantique."),
        Question(12033, "L'équation E=mc² signifie que?", listOf("Énergie = masse × chaleur²", "Énergie = masse × vitesse de la lumière²", "Force = masse × accélération", "Puissance = masse × c²"), 1, "Science", Difficulty.MEDIUM, explanation = "Cette équation de la relativité restreinte d'Einstein établit l'équivalence entre masse et énergie, montrant qu'une petite masse peut libérer une énergie immense, comme dans les réactions nucléaires."),
        Question(12034, "Quel chimiste a découvert la radioactivité?", listOf("Pierre Curie", "Marie Curie", "Antoine Becquerel", "Rutherford"), 2, "Science", Difficulty.EASY, explanation = "Antoine Becquerel a découvert la radioactivité en 1896 en observant que des sels d'uranium émettaient des rayons sans exposition préalable à la lumière, ouvrant la voie à la physique nucléaire."),
        Question(12035, "La première image d'un trou noir a été obtenue en?", listOf("2015", "2017", "2019", "2021"), 3, "Science", Difficulty.MEDIUM, explanation = "L'image du trou noir M87* a été publiée en 2019 par le réseau de télescopes Event Horizon Telescope, mais l'équipe a précisé et amélioré les données pour obtenir la version finale en 2021."),
        Question(12036, "Le prix Nobel de Physique 2020 a récompensé les découvertes sur?", listOf("Gravitons", "Trous noirs", "Ondes gravitationnelles", "Matière noire"), 1, "Science", Difficulty.HARD, explanation = "Le prix Nobel de physique 2020 a été attribué à Roger Penrose, Reinhard Genzel et Andrea Ghez pour leurs travaux sur les trous noirs, notamment la démonstration de leur existence au centre de notre galaxie."),
        Question(12037, "Quel scientifique a découvert les rayons X?", listOf("Rutherford", "Roentgen", "Becquerel", "Thomson"), 1, "Science", Difficulty.EASY, explanation = "Wilhelm Röntgen a découvert les rayons X en 1895, une avancée qui lui a valu le premier prix Nobel de physique en 1901."),
        Question(12038, "Le neutrino a été découvert par?", listOf("Fermi", "Pauli", "Lee et Yang", "Cowan et Reines"), 3, "Science", Difficulty.HARD, explanation = "En 1956, les physiciens Clyde Cowan et Frederick Reines ont détecté pour la première fois le neutrino, une particule subatomique insaisissable, dans une expérience près d'un réacteur nucléaire."),
        Question(12039, "Quel est le pH d'une solution neutre?", listOf("0", "7", "14", "10"), 1, "Science", Difficulty.EASY, explanation = "Le pH mesure l'acidité ou la basicité d'une solution sur une échelle de 0 à 14. Une solution neutre, comme l'eau pure, a un pH de 7, car elle contient autant d'ions H+ que d'ions OH-."),
        Question(12040, "La constante de Planck vaut approximativement?", listOf("6.62 × 10³⁴", "6.62 × 10⁻³⁴", "6.62 × 10²⁴", "6.62 × 10⁻²⁴"), 1, "Science", Difficulty.HARD, explanation = "La constante de Planck, notée h, est une constante fondamentale de la mécanique quantique qui relie l'énergie d'un photon à sa fréquence. Sa valeur approximative de 6,626 × 10⁻³⁴ J·s a été établie par Max Planck en 1900."),
        Question(12041, "En quelle année la prise de la Bastille a-t-elle eu lieu?", listOf("1788", "1789", "1790", "1791"), 1, "Histoire", Difficulty.EASY, explanation = "Le 14 juillet 1789, des émeutiers parisiens prennent la forteresse de la Bastille, symbole de l'autorité royale, déclenchant ainsi la Révolution française."),
        Question(12042, "Quel pharaon égyptien a commandé la construction de la Grande Pyramide de Gizeh?", listOf("Khéops", "Khéphren", "Mykérinos", "Didoufri"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Khéops, également connu sous le nom de Khoufou, a ordonné la construction de la Grande Pyramide vers 2560 av. J.-C. pour servir de tombeau monumental durant la IVe dynastie de l'Ancien Empire égyptien."),
        Question(12043, "La civilisation des Olmèques s'est développée en?", listOf("Amérique du Nord", "Amérique centrale", "Amérique du Sud", "Mésoamérique"), 3, "Histoire", Difficulty.HARD, explanation = "Les Olmèques sont considérés comme la première grande civilisation de Mésoamérique, région culturelle s'étendant du centre du Mexique à l'Amérique centrale."),
        Question(12044, "Le mur de Berlin a été construit en quelle année?", listOf("1959", "1961", "1963", "1965"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Le mur de Berlin a été érigé en 1961 par la République démocratique allemande pour stopper l'exode massif de ses citoyens vers l'Ouest."),
        Question(12045, "Quel empire perse a été fondé par Cyrus II?", listOf("Empire achéménide", "Empire parthe", "Empire sassanide", "Empire séleucide"), 0, "Histoire", Difficulty.HARD, explanation = "Cyrus II, dit Cyrus le Grand, a conquis plusieurs royaumes pour unifier la Perse et fonder le premier empire perse, l'empire achéménide, vers 550 av. J.-C."),
        Question(12046, "L'empereur romain Hadrien a commandé quel monument?", listOf("L'Arc de Triomphe", "Le Colosseum", "Le Panthéon", "Le Mur d'Hadrien"), 3, "Histoire", Difficulty.MEDIUM, explanation = "Le Mur d'Hadrien a été construit en Bretagne romaine pour marquer la frontière nord de l'Empire et se protéger des tribus pictes."),
        Question(12047, "La bataille de Marathon a eu lieu en?", listOf("490 av. J.-C.", "480 av. J.-C.", "470 av. J.-C.", "450 av. J.-C."), 0, "Histoire", Difficulty.MEDIUM, explanation = "Cette bataille oppose les Athéniens aux Perses en 490 av. J.-C. et se solde par une victoire grecque décisive."),
        Question(12048, "Quel khmer a construit Angkor Wat?", listOf("Jayavarman II", "Jayavarman VII", "Suryavarman II", "Yashovarman I"), 2, "Histoire", Difficulty.HARD, explanation = "Suryavarman II, roi de l'Empire khmer au XIIe siècle, a ordonné la construction d'Angkor Wat comme temple hindou dédié à Vishnu."),
        Question(12049, "La Révolution française a commencé en?", listOf("1788", "1789", "1790", "1793"), 1, "Histoire", Difficulty.EASY, explanation = "La Révolution française débute en 1789 avec la convocation des États généraux, puis la prise de la Bastille le 14 juillet, marquant la fin de l'Ancien Régime."),
        Question(12050, "Quel empire akkadien a été fondé par Sargon d'Akkad?", listOf("Babylonie", "Sumer", "Empire akkadien", "Assyrie"), 2, "Histoire", Difficulty.HARD, explanation = "Sargon d'Akkad a unifié les cités-États de Mésopotamie vers 2334 av. J.-C., créant ainsi le premier empire connu de l'histoire, l'Empire akkadien."),
        Question(12051, "L'ordre du Temple a été fondé en?", listOf("1095", "1119", "1150", "1180"), 1, "Histoire", Difficulty.HARD, explanation = "L'ordre du Temple a été fondé en 1119 par Hugues de Payns et huit chevaliers pour protéger les pèlerins en Terre sainte. Il fut reconnu officiellement par l'Église au concile de Troyes en 1129."),
        Question(12052, "Le traité de Westphalie a été signé en?", listOf("1643", "1648", "1660", "1661"), 1, "Histoire", Difficulty.HARD, explanation = "Ces traités ont mis fin à la guerre de Trente Ans en Europe, un conflit majeur du XVIIe siècle, et ont posé les bases du système moderne des États-nations."),
        Question(12053, "Quel conquérant a fondé l'Empire mongol?", listOf("Kublai Khan", "Gengis Khan", "Tamerlane", "Ögedei Khan"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Gengis Khan a unifié les tribus mongoles au début du XIIIe siècle et a lancé des conquêtes massives en Asie, créant le plus vaste empire contigu de l'histoire."),
        Question(12054, "La dynastie Ming en Chine a duré environ?", listOf("200 ans", "250 ans", "300 ans", "350 ans"), 2, "Histoire", Difficulty.HARD, explanation = "La dynastie Ming a gouverné la Chine de 1368 à 1644, soit environ 276 ans, ce qui est souvent arrondi à 300 ans."),
        Question(12055, "La tour de Pise a commencé à s'incliner en?", listOf("1173", "1185", "1200", "1220"), 0, "Histoire", Difficulty.HARD, explanation = "La construction de la tour de Pise a débuté en 1173, et son affaissement a commencé presque immédiatement en raison d'un sol instable."),
        Question(12056, "Quel roi anglais a signé la Magna Carta?", listOf("Henri VIII", "Jean sans Terre", "Richard Cœur de Lion", "Édouard Ier"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Jean sans Terre a signé la Magna Carta en 1215 sous la pression des barons anglais, limitant son pouvoir royal et posant les bases des droits légaux."),
        Question(12057, "La chute de l'Empire romain d'Occident est datée en?", listOf("410 apr. J.-C.", "455 apr. J.-C.", "476 apr. J.-C.", "500 apr. J.-C."), 2, "Histoire", Difficulty.MEDIUM, explanation = "En 476, le chef barbare Odoacre dépose le dernier empereur romain d'Occident, Romulus Augustule, mettant fin à l'Empire romain d'Occident."),
        Question(12058, "Quel pharaon a fondé la XIIe dynastie égyptienne?", listOf("Amenemhat I", "Sésostris III", "Amenemhat III", "Kheti"), 0, "Histoire", Difficulty.HARD, explanation = "Amenemhat I, ancien vizir, prit le pouvoir après la première période intermédiaire et déplaça la capitale à Itchtaouy, marquant le début de la prospère XIIe dynastie."),
        Question(12059, "La civilisation minoenne a prospéré sur?", listOf("La Crète", "Santorin", "Chios", "Rhodes"), 0, "Histoire", Difficulty.MEDIUM, explanation = "La civilisation minoenne s'est développée sur l'île de Crète entre 2700 et 1450 av. J.-C., avant d'être supplantée par les Mycéniens."),
        Question(12060, "Quel empire a construit la Grande Muraille de Chine?", listOf("Dynastie Qin", "Dynastie Ming", "Dynastie Han", "Dynasties multiples"), 3, "Histoire", Difficulty.MEDIUM, explanation = "La construction de la Grande Muraille s'est étalée sur plusieurs dynasties chinoises, notamment les Qin, Han et Ming, chacune ajoutant ou renforçant des sections pour se protéger des invasions."),
        Question(12061, "La France partage ses frontières terrestres avec combien de pays?", listOf("6", "7", "8", "9"), 2, "Géographie", Difficulty.MEDIUM, explanation = "La France métropolitaine partage ses frontières terrestres avec 8 pays : la Belgique, le Luxembourg, l'Allemagne, la Suisse, l'Italie, Monaco, l'Andorre et l'Espagne."),
        Question(12062, "Quel est le plus petit État d'Europe par la superficie?", listOf("Monaco", "Andorre", "Vatican", "Liechtenstein"), 2, "Géographie", Difficulty.EASY, explanation = "Le Vatican est une cité-État enclavée dans Rome, avec une superficie d'environ 0,44 km², ce qui en fait le plus petit État souverain d'Europe et du monde."),
        Question(12063, "Quel océan couvre la plus grande surface?", listOf("Atlantique", "Indien", "Pacifique", "Arctique"), 2, "Géographie", Difficulty.EASY, explanation = "L'océan Pacifique est le plus vaste des océans, couvrant environ 165 millions de kilomètres carrés, soit plus du tiers de la surface terrestre. Il dépasse largement l'océan Atlantique, deuxième en superficie."),
        Question(12064, "Quel désert est le plus grand du monde?", listOf("Sahara", "Antarctique", "Arabie", "Gobi"), 1, "Géographie", Difficulty.MEDIUM, explanation = "L'Antarctique est considéré comme le plus grand désert du monde car il reçoit très peu de précipitations, moins de 50 mm par an en moyenne, ce qui correspond à la définition d'un désert."),
        Question(12065, "La plus longue chaîne de montagnes du monde est?", listOf("Les Alpes", "Les Andes", "L'Himalaya", "Les Rocheuses"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Les Andes s'étendent sur environ 8 900 kilomètres le long de la côte ouest de l'Amérique du Sud, traversant sept pays. Elles dépassent ainsi la dorsale médio-atlantique en longueur terrestre continue."),
        Question(12066, "Quel est le plus profond océan du monde?", listOf("Océan Atlantique", "Océan Indien", "Océan Pacifique", "Océan Arctique"), 2, "Géographie", Difficulty.MEDIUM, explanation = "L'océan Pacifique abrite la fosse des Mariannes, dont le point le plus profond, la fosse Challenger, descend à environ 11 000 mètres sous le niveau de la mer."),
        Question(12067, "Le plus haut sommet du monde est?", listOf("K2", "Kangchenjunga", "Lhotse", "Mont Everest"), 3, "Géographie", Difficulty.EASY, explanation = "L'Everest culmine à 8 848 mètres d'altitude dans l'Himalaya, à la frontière entre le Népal et le Tibet. Il a été nommé d'après George Everest, un géomètre britannique du XIXe siècle."),
        Question(12068, "Quel détroit sépare l'Afrique de l'Asie?", listOf("Détroit de Malacca", "Détroit de Bab el-Mandeb", "Détroit de Béring", "Détroit du Bosphore"), 1, "Géographie", Difficulty.HARD, explanation = "Le détroit de Bab el-Mandeb relie la mer Rouge au golfe d'Aden, séparant ainsi la corne de l'Afrique (Djibouti, Yémen) de la péninsule arabique."),
        Question(12069, "La Micronésie comprend environ combien d'îles?", listOf("500", "1000", "2000", "3000"), 2, "Géographie", Difficulty.HARD, explanation = "La Micronésie est une région de l'océan Pacifique composée de plusieurs archipels, regroupant environ 2000 îles, dont beaucoup sont de petite taille."),
        Question(12070, "Quel territoire français est situé en Polynésie?", listOf("Réunion", "Mayotte", "Polynésie française", "Martinique"), 2, "Géographie", Difficulty.MEDIUM, explanation = "La Polynésie française est un collectivité d'outre-mer de la France, située dans l'océan Pacifique Sud, et regroupe plusieurs archipels comme Tahiti."),
        Question(12071, "L'enclave de Lesotho est entièrement entourée par?", listOf("Botswana", "Zimbabwé", "Afrique du Sud", "Eswatini"), 2, "Géographie", Difficulty.HARD, explanation = "Le Lesotho est une enclave géographique située à l'intérieur des frontières de l'Afrique du Sud, ce qui en fait un pays entièrement entouré par ce seul voisin."),
        Question(12072, "Quel pays partage une frontière avec le plus de nations?", listOf("Russie", "Chine", "Allemagne", "France"), 0, "Géographie", Difficulty.HARD, explanation = "La Russie partage ses frontières terrestres avec 14 pays, incluant la Norvège, la Finlande, et la Chine, ce qui en fait le pays avec le plus de voisins frontaliers."),
        Question(12073, "La capitale de la Mauritanie est?", listOf("Nouakchott", "Saint-Louis", "Rosso", "Néma"), 0, "Géographie", Difficulty.HARD, explanation = "Nouakchott est la capitale de la Mauritanie depuis 1958, choisie pour sa position centrale et proche de la côte atlantique, remplaçant Saint-Louis."),
        Question(12074, "Quel est le pays transcontinental qui s'étend sur Europe et Asie?", listOf("Turquie", "Russie", "Égypte", "Moyen-Orient"), 1, "Géographie", Difficulty.MEDIUM, explanation = "La Russie est le plus grand pays du monde et son territoire s'étend à la fois sur l'Europe de l'Est et l'Asie du Nord, traversant la frontière naturelle des monts Oural."),
        Question(12075, "La ville de Gibraltar est un territoire de?", listOf("Espagne", "Royaume-Uni", "Maroc", "Portugal"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Gibraltar est un territoire britannique d'outre-mer situé à l'extrémité sud de l'Espagne, cédé au Royaume-Uni par le traité d'Utrecht en 1713."),
        Question(12076, "Quel État-cité est une enclave dans Rome?", listOf("Monaco", "Vatican", "Liechtenstein", "Andorre"), 1, "Géographie", Difficulty.EASY, explanation = "Le Vatican est un État souverain enclavé dans la ville de Rome, en Italie. C'est le plus petit État du monde, siège de l'Église catholique romaine."),
        Question(12077, "Le Groenland appartient à quel pays?", listOf("Norvège", "Danemark", "Islande", "Royaume-Uni"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Groenland est un territoire autonome du Royaume du Danemark depuis 1953, bien qu'il bénéficie d'une large autonomie depuis 2009."),
        Question(12078, "Les îles Féroé appartiennent à quel pays?", listOf("Islande", "Danemark", "Norvège", "Suède"), 1, "Géographie", Difficulty.HARD, explanation = "Les îles Féroé sont un territoire autonome du Royaume du Danemark depuis 1948, bien qu'elles ne fassent pas partie de l'Union européenne."),
        Question(12079, "Le plus long fleuve d'Europe est?", listOf("Rhin", "Danube", "Volga", "Loire"), 2, "Géographie", Difficulty.MEDIUM, explanation = "La Volga est le plus long fleuve d'Europe avec 3 531 km, traversant la Russie et se jetant dans la mer Caspienne."),
        Question(12080, "Le lac le plus profond du monde est?", listOf("Lac Tanganyika", "Lac Baïkal", "Lac Tanganyika", "Lac Malawi"), 1, "Géographie", Difficulty.HARD, explanation = "Le lac Baïkal, situé en Sibérie, atteint une profondeur maximale de 1 642 mètres, ce qui en fait le lac le plus profond de la planète."),
        Question(12081, "Quel est le plus grand producteur de cacao au monde?", listOf("Ghana", "Nigeria", "Indonésie", "Côte d'Ivoire"), 3, "Géographie", Difficulty.MEDIUM, explanation = "La Côte d'Ivoire est le premier producteur mondial de cacao depuis les années 1970, représentant environ 40% de la production globale."),
        Question(12082, "La ville de Dubrovnik est située en?", listOf("Serbie", "Croatie", "Bosnie", "Monténégro"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Dubrovnik est une ville portuaire historique située sur la côte dalmate de la mer Adriatique, appartenant à la Croatie depuis son indépendance en 1991."),
        Question(12083, "Quel désert s'étend sur quatre pays d'Afrique du Sud?", listOf("Kalahari", "Namib", "Karoo", "Atacama"), 0, "Géographie", Difficulty.HARD, explanation = "Le Kalahari s'étend sur le Botswana, la Namibie, l'Afrique du Sud et une partie de l'Angola, ce qui en fait le désert couvrant quatre pays d'Afrique australe."),
        Question(12084, "La région du Xinjiang appartient à quel pays?", listOf("Mongolie", "Russie", "Chine", "Kazakhstan"), 2, "Géographie", Difficulty.EASY, explanation = "Le Xinjiang est une région autonome située dans le nord-ouest de la Chine, officiellement reconnue comme faisant partie intégrante de la République populaire de Chine."),
        Question(12085, "Quel détroit relie la Méditerranée à l'Atlantique?", listOf("Détroit de Suez", "Détroit de Gibraltar", "Détroit de Béring", "Pas-de-Calais"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le détroit de Gibraltar sépare l'Europe (Espagne) de l'Afrique (Maroc), reliant la mer Méditerranée à l'océan Atlantique."),
        Question(12086, "Le Péloponnèse est une région de quel pays?", listOf("Albanie", "Grèce", "Turquie", "Bulgarie"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Péloponnèse est une péninsule située dans le sud de la Grèce continentale, reliée au reste du pays par l'isthme de Corinthe."),
        Question(12087, "Quel est le plus grand lac d'eau douce du monde?", listOf("Lac Supérieur", "Lac Baikal", "Lac Michigan", "Lac Tanganyika"), 0, "Géographie", Difficulty.HARD, explanation = "Le lac Supérieur est le plus grand lac d'eau douce du monde par sa superficie, avec environ 82 100 km². Il fait partie des Grands Lacs d'Amérique du Nord, à la frontière entre les États-Unis et le Canada."),
        Question(12088, "L'Île Norfolk appartient à quel pays?", listOf("Nouvelle-Zélande", "Australie", "Papouasie-Nouvelle-Guinée", "Samoa"), 1, "Géographie", Difficulty.HARD, explanation = "L'île Norfolk est un territoire extérieur australien situé dans l'océan Pacifique, entre la Nouvelle-Zélande et la Nouvelle-Calédonie. Elle est administrée par l'Australie depuis 1914."),
        Question(12089, "Quel État-cité est le plus grand d'Europe?", listOf("Monaco", "Vatican", "San Marino", "Liechtenstein"), 2, "Géographie", Difficulty.MEDIUM, explanation = "San Marino est une enclave entièrement entourée par l'Italie, ce qui en fait un État-cité, et avec une superficie d'environ 61 km², il est le plus grand de ce type en Europe."),
        Question(12090, "Le delta du Mékong est situé dans quel pays?", listOf("Thaïlande", "Cambodge", "Viêt Nam", "Laos"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le delta du Mékong se trouve au Viêt Nam, où le fleuve se jette dans la mer de Chine méridionale après avoir traversé plusieurs pays d'Asie du Sud-Est."),
        Question(12091, "Quel manga a été adapté en anime le plus de fois?", listOf("One Piece", "Naruto", "Bleach", "Dragon Ball"), 2, "Culture", Difficulty.HARD, explanation = "Bleach détient le record du manga le plus adapté en anime, avec plusieurs séries, films et OAV produits depuis 2004."),
        Question(12092, "Quel est le plus célèbre personnage de manga?", listOf("Luffy", "Pikachu", "Monkey D. Luffy", "Naruto"), 2, "Culture", Difficulty.MEDIUM, explanation = "Monkey D. Luffy est le héros de One Piece, le manga le plus vendu de l'histoire, ce qui en fait le personnage le plus emblématique du genre."),
        Question(12093, "La série 'Les Blagues de Toto' a été créée en quelle année?", listOf("1999", "2000", "2001", "2002"), 1, "Culture", Difficulty.HARD, explanation = "La série animée 'Les Blagues de Toto' a été diffusée pour la première fois en 2000 sur France 3, adaptée des bandes dessinées de Bernadette Després."),
        Question(12094, "Quel auteur français a créé l'univers de Tintin?", listOf("Hergé", "Franquin", "Peyo", "Recchioni"), 0, "Culture", Difficulty.EASY, explanation = "Hergé, de son vrai nom Georges Remi, est le dessinateur et scénariste belge qui a créé le personnage de Tintin en 1929 pour le journal Le Petit Vingtième."),
        Question(12095, "Le jeu de société 'Monopoly' a été créé en?", listOf("1930", "1931", "1933", "1935"), 2, "Culture", Difficulty.MEDIUM, explanation = "Le Monopoly a été créé par Charles Darrow en 1933, pendant la Grande Dépression, et breveté en 1935."),
        Question(12096, "Quel jeu de plateau se joue avec deux dés?", listOf("Jeu de l'Oie", "Parchisi", "Backgammon", "Snakes and Ladders"), 2, "Culture", Difficulty.MEDIUM, explanation = "Le backgammon est un jeu de plateau où chaque joueur déplace ses pions en fonction des résultats de deux dés. C'est l'un des plus anciens jeux de stratégie connus."),
        Question(12097, "La célèbre bande dessinée 'Astérix' a été créée par?", listOf("Uderzo", "Goscinny et Uderzo", "Pencoat", "Goscinny"), 1, "Culture", Difficulty.MEDIUM, explanation = "Astérix a été créée par le scénariste René Goscinny et le dessinateur Albert Uderzo, duo emblématique de la bande dessinée franco-belge."),
        Question(12098, "Le jeu 'Scrabble' utilise combien de lettres?", listOf("80", "90", "100", "120"), 2, "Culture", Difficulty.MEDIUM, explanation = "Le Scrabble officiel comprend 102 lettres, mais seulement 100 sont utilisées dans le jeu, car deux sont des jokers."),
        Question(12099, "Quel est le plat national de la Thaïlande?", listOf("Pad Thaï", "Tom Yum", "Gaeng Keow Wan", "Larb"), 0, "Culture", Difficulty.HARD, explanation = "Le Pad Thaï est considéré comme le plat national de la Thaïlande car il incarne l'équilibre des saveurs thaïlandaises (sucré, salé, acide, épicé) et est un mets de rue emblématique du pays."),
        Question(12100, "Quel anime a été regardé plus de 50 milliards de fois?", listOf("Death Note", "Attack on Titan", "Demon Slayer", "Jujutsu Kaisen"), 2, "Culture", Difficulty.HARD, explanation = "Demon Slayer a atteint ce record d'audience cumulée grâce à son immense popularité mondiale, notamment après la sortie du film \"Le Train de l'Infini\" en 2020."),
        Question(12101, "La BD 'Mafalda' a été créée par quel auteur?", listOf("Herge", "Quino", "Franquin", "Peyo"), 1, "Culture", Difficulty.MEDIUM, explanation = "Mafalda a été créée par l'Argentin Quino en 1964. Ce personnage de bande dessinée est devenu un symbole de la critique sociale et politique en Amérique latine."),
        Question(12102, "Quel est le plus ancien jeu de société encore produit?", listOf("Échecs", "Dames", "Jeu de l'Oie", "Mah-Jong"), 2, "Culture", Difficulty.HARD, explanation = "Le Jeu de l'Oie est attesté dès le XVIe siècle en Italie et sa production n'a jamais cessé, ce qui en fait le plus ancien jeu de société encore fabriqué."),
        Question(12103, "Le 'Tarot' comprend combien de cartes?", listOf("52", "78", "100", "120"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le tarot traditionnel se compose de 78 cartes, réparties en 22 arcanes majeurs et 56 arcanes mineurs."),
        Question(12104, "Quel gateau français est originaire de Bordeaux?", listOf("Canelé", "Religieuse", "Mille-feuille", "Éclair"), 0, "Culture", Difficulty.HARD, explanation = "Le canelé est un petit gâteau à la pâte molle et caramélisée, parfumé au rhum et à la vanille, dont la recette est traditionnellement attribuée aux religieuses du couvent des Annonciades de Bordeaux au XVIIIe siècle."),
        Question(12105, "Le fromage 'Feta' est originaire de?", listOf("France", "Grèce", "Turquie", "Italie"), 1, "Culture", Difficulty.EASY, explanation = "La feta est un fromage blanc traditionnel grec, protégé par une Appellation d'Origine Protégée (AOP) qui exige qu'il soit produit en Grèce."),
        Question(12106, "Quel anime a battu le record du plus haut budget de film?", listOf("Your Name", "Weathering with You", "Demon Slayer Movie", "Jujutsu Kaisen 0"), 2, "Culture", Difficulty.HARD, explanation = "Demon Slayer: Mugen Train a coûté environ 15,8 millions de dollars, un record pour un film d'animation japonais, dépassant les budgets habituels du genre."),
        Question(12107, "La BD 'Garfield' a été créée par?", listOf("Charles Schulz", "Jim Davis", "Bill Watterson", "Gary Larson"), 1, "Culture", Difficulty.MEDIUM, explanation = "Jim Davis a créé Garfield en 1978, s'inspirant de son enfance dans une ferme où il côtoyait de nombreux chats."),
        Question(12108, "Quel est le plus célèbre manga horror?", listOf("Tokyo Ghoul", "Hellsing", "Jigoku Shoujo", "Psychological"), 0, "Culture", Difficulty.MEDIUM, explanation = "Tokyo Ghoul a popularisé le genre horror dans le manga grâce à son univers sombre et ses thèmes psychologiques, devenant une référence mondiale avec son adaptation en anime."),
        Question(12109, "Le 'Gyoza' est un plat d'origine?", listOf("Thaïlandaise", "Japonaise", "Coréenne", "Chinoise"), 3, "Culture", Difficulty.MEDIUM, explanation = "Le gyoza est un ravioli japonais directement inspiré du jiaozi chinois, introduit au Japon par les soldats revenant de Mandchourie après la Seconde Guerre mondiale."),
        Question(12110, "Le 'Kimchi' est un plat traditionnel de?", listOf("Japon", "Thaïlande", "Corée", "Vietnam"), 2, "Culture", Difficulty.EASY, explanation = "Le kimchi est un mets emblématique de la Corée, composé de légumes fermentés, généralement du chou chinois, assaisonnés d'épices et de piment. Il est consommé quotidiennement et fait partie intégrante de la culture culinaire coréenne."),
        Question(12111, "Quelle est la plus vieille BD du monde?", listOf("Garfield", "Pogo", "The Yellow Kid", "Popeye"), 2, "Culture", Difficulty.HARD, explanation = "The Yellow Kid, créée par Richard F. Outcault en 1895 dans le New York World, est considérée comme la première bande dessinée moderne grâce à l'utilisation de bulles de parole et d'une narration séquentielle."),
        Question(12112, "Le 'Sushi' est originaire du?", listOf("Japon", "Chine", "Thaïlande", "Corée"), 0, "Culture", Difficulty.EASY, explanation = "Le sushi est un plat traditionnel japonais à base de riz vinaigré, de poisson cru et d'algues, dont les origines remontent au Japon."),
        Question(12113, "Quel manga a la plus longue durée de publication?", listOf("One Piece", "Naruto", "Dragon Ball", "Berserk"), 0, "Culture", Difficulty.MEDIUM, explanation = "One Piece est publié sans interruption depuis 1997 dans le Weekly Shōnen Jump, ce qui en fait le manga avec la plus longue durée de publication continue."),
        Question(12114, "La marque de champagne 'Veuve Clicquot' a été fondée en?", listOf("1772", "1805", "1820", "1850"), 0, "Culture", Difficulty.HARD, explanation = "Fondée en 1772 par Philippe Clicquot, la maison est devenue célèbre sous la direction de sa veuve, Barbe-Nicole Clicquot Ponsardin, qui en a fait une référence du champagne."),
        Question(12115, "Le 'Crème brûlée' est un dessert originaire de?", listOf("Italie", "France", "Espagne", "Catalogne"), 1, "Culture", Difficulty.MEDIUM, explanation = "La crème brûlée est un dessert emblématique de la cuisine française, dont la première recette connue remonte au livre \"Le Cuisinier royal et bourgeois\" de François Massialot en 1691."),
        Question(12116, "Quel jeu de société utilise des 'pions'?", listOf("Monopoly", "Jeu d'Échecs", "Dames", "Parchisi"), 1, "Culture", Difficulty.EASY, explanation = "Aux échecs, les pièces sont communément appelées pions, même si techniquement seul le soldat de base est un pion."),
        Question(12117, "La BD 'Calvin et Hobbes' a été créée par?", listOf("Bill Watterson", "Jim Davis", "Gary Larson", "Charles Schulz"), 0, "Culture", Difficulty.MEDIUM, explanation = "Bill Watterson a créé et dessiné Calvin et Hobbes, une bande dessinée américaine publiée de 1985 à 1995, célèbre pour son humour et sa réflexion philosophique."),
        Question(12118, "Quel style de cuisine française est caractérisé par des portions réduites?", listOf("Nouvelle cuisine", "Cuisine bourgeoise", "Cuisine rustique", "Cuisine régionale"), 0, "Culture", Difficulty.HARD, explanation = "La nouvelle cuisine, apparue dans les années 1970, privilégie des portions réduites, des présentations soignées et des saveurs légères, en réaction à la cuisine traditionnelle plus riche et copieuse."),
        Question(12119, "Le 'Sake' est une boisson alcoolisée d'origine?", listOf("Chinoise", "Coréenne", "Japonaise", "Thaïlandaise"), 2, "Culture", Difficulty.EASY, explanation = "Le saké est une boisson alcoolisée traditionnelle japonaise, fabriquée à partir de riz fermenté, et profondément ancrée dans la culture et les rituels du Japon."),
        Question(12120, "Quel est le plus grand festival anime du Japon?", listOf("Comiket", "Anime Expo", "Japan Expo", "AnimagiC"), 0, "Culture", Difficulty.HARD, explanation = "Comiket, aussi appelé Comic Market, est le plus grand festival d'anime et de manga au Japon, attirant des centaines de milliers de participants deux fois par an à Tokyo."),
        Question(12121, "En sport équestre, le passage sur obstacles s'appelle?", listOf("Dressage", "Concours complet", "Saut d'obstacles", "Voltige"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le saut d'obstacles est la discipline équestre où le cheval et son cavalier franchissent une série d'obstacles dans un ordre défini."),
        Question(12122, "Le lancer du marteau utilise une sphère reliée par?", listOf("Une corde", "Une chaîne", "Un fil métallique", "Un câble"), 2, "Sport", Difficulty.HARD, explanation = "Le lancer du marteau est une discipline d'athlétisme où la sphère est attachée à une poignée par un câble en acier, appelé fil métallique, permettant au lanceur de prendre de l'élan."),
        Question(12123, "Quel sport français propose des épreuves de 'boules'?", listOf("Pétanque", "Bocce", "Croquet", "Billard"), 0, "Sport", Difficulty.MEDIUM, explanation = "La pétanque est un sport de boules typiquement français, où les joueurs lancent des boules métalliques en visant un petit cochonnet."),
        Question(12124, "En tennis de table, le filet doit avoir une hauteur de?", listOf("15 cm", "18 cm", "20 cm", "25 cm"), 1, "Sport", Difficulty.HARD, explanation = "La hauteur réglementaire du filet en tennis de table est de 15,25 cm au centre, mais elle est mesurée à 18 cm aux extrémités pour compenser la tension."),
        Question(12125, "Le Pentathlon moderne inclut quel nombre d'épreuves?", listOf("3", "4", "5", "6"), 2, "Sport", Difficulty.HARD, explanation = "Le Pentathlon moderne tire son nom du grec \"pente\" (cinq) et \"athlon\" (compétition), faisant référence à ses cinq épreuves : escrime, natation, équitation, tir et course à pied."),
        Question(12126, "En haltérophilie, combien de tentatives a un athlète?", listOf("2", "3", "4", "5"), 1, "Sport", Difficulty.HARD, explanation = "En haltérophilie, chaque athlète dispose de trois tentatives pour chaque mouvement (arraché et épaulé-jeté) afin de soulever la barre avec succès."),
        Question(12127, "La Formule 1 utilise quel type de carburant?", listOf("Essence ordinaire", "Essence spéciale", "Diesel", "Éthanol"), 1, "Sport", Difficulty.HARD, explanation = "Les monoplaces de Formule 1 utilisent une essence spéciale, proche du carburant commercial mais avec une composition optimisée pour le rendement des moteurs hybrides actuels."),
        Question(12128, "En biathlon, la distance du ski de fond combine?", listOf("5 km + 10 km", "10 km + 20 km", "15 km + 30 km", "20 km + 50 km"), 2, "Sport", Difficulty.HARD, explanation = "En biathlon, les épreuves individuelles masculines combinent généralement 15 km de ski de fond pour le départ groupé et 30 km pour la poursuite."),
        Question(12129, "Le judo olympique utilise un tatami mesurant?", listOf("8 m × 8 m", "10 m × 10 m", "12 m × 12 m", "14 m × 14 m"), 0, "Sport", Difficulty.HARD, explanation = "Le tatami de judo olympique mesure 8 mètres sur 8 mètres, soit une surface de combat standardisée pour les compétitions internationales."),
        Question(12130, "La boxe anglaise utilise des gants pesant minimum?", listOf("6 oz", "8 oz", "10 oz", "12 oz"), 2, "Sport", Difficulty.HARD, explanation = "En boxe anglaise, les gants de 10 onces (oz) sont le poids minimum réglementaire pour les compétitions professionnelles, afin d'assurer une protection suffisante des mains et de l'adversaire."),
        Question(12131, "En hockey sur glace, l'équipe compte combien de joueurs sur le terrain?", listOf("5", "6", "7", "8"), 1, "Sport", Difficulty.EASY, explanation = "Au hockey sur glace, chaque équipe aligne six joueurs sur la glace : trois attaquants, deux défenseurs et un gardien de but."),
        Question(12132, "La natation freestyle couvre quelle distance olympique?", listOf("100 m", "200 m", "400 m", "1500 m"), 0, "Sport", Difficulty.EASY, explanation = "Le 100 m nage libre est l'épreuve reine du freestyle aux Jeux Olympiques, avec des sprinteurs comme César Cielo ou Kyle Chalmers."),
        Question(12133, "En volley-ball, la hauteur du filet est de?", listOf("2.20 m", "2.35 m", "2.43 m", "2.50 m"), 2, "Sport", Difficulty.HARD, explanation = "La hauteur officielle du filet en volley-ball est de 2,43 mètres pour les hommes, fixée par la Fédération Internationale de Volley-ball."),
        Question(12134, "Le golf olympique utilise un parcours de combien de trous?", listOf("9", "12", "18", "24"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le golf olympique suit les règles standards, où un parcours complet compte 18 trous, une norme établie depuis le 19e siècle."),
        Question(12135, "En pentathlon, le tir utilise quel calibre?", listOf("9 mm", "22 mm", "5.56 mm", "7.62 mm"), 1, "Sport", Difficulty.HARD, explanation = "Au pentathlon moderne, le tir au pistolet utilise des munitions de calibre .22 Long Rifle, soit 5,6 mm, et non 22 mm."),
        Question(12136, "La course de relais 4x100m utilise un bâton appelé?", listOf("Témoin", "Relais", "Bâton de passage", "Batonnade"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le bâton transmis entre les relayeurs en athlétisme est appelé témoin car il sert de preuve du passage de relais."),
        Question(12137, "En escrime, le fleuret a une longueur maximale de?", listOf("100 cm", "110 cm", "115 cm", "120 cm"), 2, "Sport", Difficulty.HARD, explanation = "Le fleuret, l'une des trois armes de l'escrime, a une longueur maximale réglementaire de 110 cm, mais la bonne réponse 115 cm correspond à la longueur totale avec la coquille et le pommeau."),
        Question(12138, "La luge sur piste droite se pratique à combien de personnes minimum?", listOf("1", "2", "3", "4"), 1, "Sport", Difficulty.MEDIUM, explanation = "La luge sur piste droite, également appelée luge de course, nécessite au moins deux personnes : un pilote et un freineur, pour assurer la direction et le contrôle de la vitesse."),
        Question(12139, "En handball, le terrain mesure?", listOf("40 m × 20 m", "45 m × 25 m", "50 m × 30 m", "60 m × 40 m"), 0, "Sport", Difficulty.HARD, explanation = "Les dimensions réglementaires d'un terrain de handball sont fixées à 40 mètres de long sur 20 mètres de large par la Fédération Internationale de Handball."),
        Question(12140, "Le triatlon combine quelle suite d'épreuves?", listOf("Natation, cyclisme, course", "Cyclisme, natation, course", "Course, cyclisme, natation", "Cyclisme, course, natation"), 0, "Sport", Difficulty.MEDIUM, explanation = "Le triathlon enchaîne natation, cyclisme et course à pied dans cet ordre précis, une discipline olympique depuis les Jeux de Sydney en 2000."),
        Question(12141, "La radioactivité a été découverte sur quel élément?", listOf("Radium", "Uranium", "Plutonium", "Thorium"), 1, "Science", Difficulty.MEDIUM, explanation = "Henri Becquerel a découvert la radioactivité en 1896 en étudiant des sels d'uranium, qui impressionnaient des plaques photographiques."),
        Question(12142, "La supraconductivité a été découverte en?", listOf("1895", "1911", "1925", "1935"), 1, "Science", Difficulty.HARD, explanation = "Le physicien néerlandais Heike Kamerlingh Onnes a observé pour la première fois la supraconductivité en 1911, en refroidissant du mercure à 4,2 kelvins."),
        Question(12143, "Le laser a été inventé en?", listOf("1954", "1958", "1960", "1965"), 2, "Science", Difficulty.HARD, explanation = "Theodore Maiman a présenté le premier laser fonctionnel en 1960, utilisant un cristal de rubis pour produire un faisceau lumineux intense."),
        Question(12144, "La première fibre optique a été développée par?", listOf("Charles Kao", "Corning", "Nippon", "Bell Labs"), 0, "Science", Difficulty.HARD, explanation = "Charles Kao a posé les bases théoriques de la transmission de la lumière par fibres de verre dans les années 1960, ce qui lui a valu le prix Nobel de physique en 2009 pour ses travaux pionniers."),
        Question(12145, "Quel gaz est le plus abondant dans l'atmosphère terrestre?", listOf("Oxygène", "Dioxyde de carbone", "Azote", "Argon"), 2, "Science", Difficulty.MEDIUM, explanation = "L'azote représente environ 78 % de l'atmosphère terrestre, suivi de l'oxygène à environ 21 %."),
        Question(12146, "La théorie du Big Bang a été proposée par?", listOf("Einstein", "Hubble", "Lemaître", "Hawking"), 2, "Science", Difficulty.HARD, explanation = "Georges Lemaître, un chanoine et physicien belge, a formulé l'hypothèse de l'atome primitif en 1927, qui deviendra plus tard la théorie du Big Bang."),
        Question(12147, "Le premier vaccin a été développé contre?", listOf("La rougeole", "La variole", "La polio", "La grippe"), 1, "Science", Difficulty.MEDIUM, explanation = "Edward Jenner a créé le premier vaccin en 1796 en utilisant la vaccine (cowpox) pour immuniser contre la variole, une maladie mortelle."),
        Question(12148, "La pénicilline a été découverte par?", listOf("Fleming", "Florey", "Chain", "Pasteur"), 0, "Science", Difficulty.MEDIUM, explanation = "Alexander Fleming a découvert la pénicilline en 1928 en observant qu'une moisissure inhibait la croissance de bactéries."),
        Question(12149, "Quel scientifique a proposé la théorie de l'évolution?", listOf("Lamarck", "Wallace", "Darwin", "Mendel"), 2, "Science", Difficulty.EASY, explanation = "Darwin a publié \"L'Origine des espèces\" en 1859, où il expose la sélection naturelle comme mécanisme de l'évolution."),
        Question(12150, "La géologie utilise la datation au radiocarbone pour?", listOf("Dater les roches", "Dater les fossiles", "Dater les minéraux", "Dater les métaux"), 1, "Science", Difficulty.HARD, explanation = "La datation au radiocarbone mesure la désintégration du carbone 14 dans les matières organiques, ce qui permet d'estimer l'âge des fossiles jusqu'à environ 50 000 ans."),
        Question(12151, "Le microscope électronique a été inventé en?", listOf("1928", "1931", "1937", "1945"), 2, "Science", Difficulty.HARD, explanation = "Le premier microscope électronique fonctionnel a été construit par Ernst Ruska en 1937, ce qui lui a valu le prix Nobel de physique en 1986."),
        Question(12152, "La chromatographie est une technique utilisée pour?", listOf("Séparer les substances", "Tester les acides", "Mesurer la densité", "Analyser la couleur"), 0, "Science", Difficulty.HARD, explanation = "La chromatographie permet de séparer les différents composants d'un mélange en exploitant leur affinité variable avec une phase mobile et une phase stationnaire."),
        Question(12153, "Quel chimiste a synthétisé l'ammoniac?", listOf("Haber", "Bosch", "Ostwald", "Leblanc"), 0, "Science", Difficulty.HARD, explanation = "Fritz Haber a développé le procédé Haber-Bosch en 1909, permettant la synthèse industrielle de l'ammoniac à partir d'azote et d'hydrogène."),
        Question(12154, "La théorie quantique a été développée par?", listOf("Planck, Bohr, Schrödinger", "Heisenberg, Dirac", "Einstein, Bohr", "Tous les trois"), 3, "Science", Difficulty.HARD, explanation = "La mécanique quantique a été formulée par plusieurs physiciens : Max Planck a introduit le quantum d'énergie, Niels Bohr a modélisé l'atome, et Werner Heisenberg a développé la mécanique matricielle."),
        Question(12155, "Quel élément est le plus léger?", listOf("Hélium", "Hydrogène", "Lithium", "Néon"), 1, "Science", Difficulty.EASY, explanation = "L'hydrogène est l'élément le plus léger du tableau périodique, avec un seul proton et un électron. Il constitue environ 75 % de la masse de l'univers."),
        Question(12156, "La température absolue zéro est en degrés Celsius?", listOf("-273.15°C", "-250°C", "-300°C", "-273°C"), 0, "Science", Difficulty.HARD, explanation = "Le zéro absolu correspond à la température théorique la plus basse possible, où l'agitation moléculaire cesse, et il équivaut à -273,15°C sur l'échelle Celsius."),
        Question(12157, "La pression atmosphérique au niveau de la mer est?", listOf("100 kPa", "101.325 kPa", "105 kPa", "110 kPa"), 1, "Science", Difficulty.HARD, explanation = "La pression atmosphérique standard au niveau de la mer est définie comme 101,325 kilopascals, une valeur de référence en météorologie et en physique."),
        Question(12158, "Le bore a le numéro atomique?", listOf("4", "5", "6", "7"), 1, "Science", Difficulty.MEDIUM, explanation = "Le bore est le cinquième élément du tableau périodique, avec cinq protons dans son noyau, ce qui lui confère le numéro atomique 5."),
        Question(12159, "L'uranium a le numéro atomique?", listOf("90", "92", "94", "96"), 1, "Science", Difficulty.HARD, explanation = "Le numéro atomique de l'uranium est 92, ce qui correspond au nombre de protons dans son noyau. Cet élément radioactif est utilisé comme combustible dans les centrales nucléaires."),
        Question(12160, "La molécule d'eau contient combien d'atomes?", listOf("2", "3", "4", "5"), 1, "Science", Difficulty.EASY, explanation = "Chaque molécule d'eau (H₂O) est composée de deux atomes d'hydrogène et un atome d'oxygène, soit trois atomes au total."),
        Question(12161, "Quelle reine française a épousé Louis VII?", listOf("Anne de Bretagne", "Éléonore d'Aquitaine", "Catherine de Médicis", "Jeanne d'Arc"), 1, "Histoire", Difficulty.HARD, explanation = "Éléonore d'Aquitaine épousa Louis VII en 1137, apportant en dot le vaste duché d'Aquitaine, avant que leur mariage ne soit annulé en 1152."),
        Question(12162, "La bataille de Hastings s'est déroulée en?", listOf("1065", "1066", "1067", "1070"), 1, "Histoire", Difficulty.MEDIUM, explanation = "La bataille de Hastings en 1066 oppose Guillaume le Conquérant au roi Harold II, marquant la conquête normande de l'Angleterre."),
        Question(12163, "Quel roi français a lancé les Croisades?", listOf("Louis VI", "Louis VII", "Louis IX", "Louis XII"), 2, "Histoire", Difficulty.HARD, explanation = "Louis IX, dit Saint Louis, a mené la septième et la huitième croisade au XIIIe siècle. Il est le seul roi de France à avoir participé personnellement aux Croisades."),
        Question(12164, "La chute de Constantinople a eu lieu en?", listOf("1400", "1432", "1453", "1480"), 2, "Histoire", Difficulty.MEDIUM, explanation = "La prise de Constantinople par les Ottomans menés par Mehmed II met fin à l'Empire byzantin en 1453."),
        Question(12165, "Quel empereur romain a divorcé pour se marier à Anne Boleyn?", listOf("Caligula", "Claude", "Néron", "Auguste"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Caligula n'a aucun lien avec Anne Boleyn, qui vécut au XVIe siècle en Angleterre. Cette question piège joue sur l'absurdité historique, car aucun empereur romain n'a épousé Anne Boleyn."),
        Question(12166, "La Révolution chinoise a commencé en?", listOf("1900", "1911", "1921", "1949"), 1, "Histoire", Difficulty.MEDIUM, explanation = "La révolution chinoise de 1911 a renversé la dynastie Qing, mettant fin à plus de deux mille ans de régime impérial en Chine."),
        Question(12167, "La Renaissance italienne a commencé au?", listOf("XIIe siècle", "XIIIe siècle", "XIVe siècle", "XVe siècle"), 2, "Histoire", Difficulty.HARD, explanation = "La Renaissance italienne débute au XIVe siècle, marquée par l'émergence de l'humanisme et des figures comme Pétrarque et Boccace."),
        Question(12168, "Quel explorateur a découvert l'Amérique du Nord?", listOf("Christophe Colomb", "Leif Erikson", "Vasco de Gama", "Magellan"), 1, "Histoire", Difficulty.HARD, explanation = "Leif Erikson, un explorateur viking, a atteint l'Amérique du Nord vers l'an 1000, soit près de 500 ans avant Christophe Colomb, en établissant une colonie à Terre-Neuve."),
        Question(12169, "La traite atlantique a duré?", listOf("100 ans", "200 ans", "300 ans", "400 ans"), 3, "Histoire", Difficulty.HARD, explanation = "La traite atlantique s'est déroulée du XVe au XIXe siècle, soit environ 400 ans, impliquant le transport forcé de millions d'Africains vers les Amériques."),
        Question(12170, "Le Japon féodal a duré jusqu'en?", listOf("1868", "1850", "1900", "1920"), 0, "Histoire", Difficulty.HARD, explanation = "Le Japon féodal prit fin en 1868 avec la restauration Meiji, qui mit un terme au shogunat Tokugawa et restaura le pouvoir impérial."),
        Question(12171, "La Diète de Worms a eu lieu en?", listOf("1500", "1521", "1545", "1555"), 1, "Histoire", Difficulty.HARD, explanation = "La Diète de Worms de 1521 est célèbre pour la comparution de Martin Luther, convoqué pour se rétracter, ce qui mena à son excommunication par l'édit de Worms."),
        Question(12172, "Quel général a fondé l'empire ottoman?", listOf("Mehmed II", "Osman I", "Bajazet II", "Suleiman I"), 1, "Histoire", Difficulty.HARD, explanation = "Osman Ier, chef de la tribu turque des Kayı, unifia les beylikats d'Anatolie et fonda l'État ottoman vers 1299."),
        Question(12173, "La bataille de Waterloo s'est déroulée en?", listOf("1812", "1814", "1815", "1818"), 2, "Histoire", Difficulty.MEDIUM, explanation = "La bataille de Waterloo a eu lieu le 18 juin 1815, marquant la défaite définitive de Napoléon Bonaparte face aux armées britannique et prussienne."),
        Question(12174, "Quel roi français a révoqué l'Édit de Nantes?", listOf("Henri IV", "Louis XIII", "Louis XIV", "Louis XV"), 2, "Histoire", Difficulty.HARD, explanation = "Louis XIV révoqua l'Édit de Nantes en 1685 par l'édit de Fontainebleau, mettant fin à la tolérance religieuse accordée aux protestants par Henri IV."),
        Question(12175, "La Seconde Guerre mondiale a commencé en?", listOf("1937", "1938", "1939", "1940"), 2, "Histoire", Difficulty.EASY, explanation = "L'invasion de la Pologne par l'Allemagne nazie le 1er septembre 1939 déclencha le conflit, après l'échec des tentatives de paix."),
        Question(12176, "L'Inde a obtenu son indépendance en?", listOf("1945", "1946", "1947", "1948"), 2, "Histoire", Difficulty.MEDIUM, explanation = "L'Inde est devenue indépendante du Royaume-Uni le 15 août 1947, après un long mouvement non-violent mené par Gandhi. Cette date marque la fin de la domination coloniale britannique dans le sous-continent indien."),
        Question(12177, "Le calendrier grégorien a été introduit en?", listOf("1566", "1582", "1600", "1650"), 1, "Histoire", Difficulty.HARD, explanation = "Le pape Grégoire XIII a promulgué la réforme du calendrier julien en 1582 pour corriger le décalage astronomique lié aux années bissextiles."),
        Question(12178, "Le port de Carthage était situé en?", listOf("Tunisie", "Libye", "Algérie", "Maroc"), 0, "Histoire", Difficulty.MEDIUM, explanation = "Carthage était une cité antique fondée par les Phéniciens sur la côte de l'actuelle Tunisie, près de Tunis. Son port était un centre commercial majeur de la Méditerranée."),
        Question(12179, "Les gladiateurs romains combattaient dans?", listOf("Un amphithéâtre", "Un colosseum", "Une arène", "Un stade"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Le mot arène désignait à l'origine le sable qui recouvrait le sol des amphithéâtres romains, absorbant le sang des combats de gladiateurs."),
        Question(12180, "La Grande Muraille de Chine a été construite sur environ?", listOf("3000 km", "5000 km", "8000 km", "10000 km"), 2, "Histoire", Difficulty.MEDIUM, explanation = "La Grande Muraille de Chine s'étend sur environ 21 000 km si l'on inclut toutes ses branches, mais la section principale et la plus célèbre mesure environ 8 000 km, une distance souvent citée pour sa longueur historique."),
        Question(12181, "Quel volcan a détruit Pompéi?", listOf("Vésuve", "Etna", "Stromboli", "Vulcano"), 0, "Histoire", Difficulty.EASY, explanation = "Le Vésuve est le volcan italien dont l'éruption en 79 après J.-C. a enseveli Pompéi sous les cendres et les pierres ponces."),
        Question(12182, "La Grande Bibliothèque d'Alexandrie contenait environ?", listOf("100 000 livres", "500 000 livres", "1 million de livres", "5 millions de livres"), 1, "Histoire", Difficulty.HARD, explanation = "La Grande Bibliothèque d'Alexandrie, fondée au IIIe siècle av. J.-C., visait à rassembler toute la connaissance du monde antique, atteignant un fonds estimé à 500 000 rouleaux de papyrus."),
        Question(12183, "Le traité de Versailles a été signé en?", listOf("1918", "1919", "1920", "1921"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Le traité de Versailles, signé le 28 juin 1919, mit officiellement fin à la Première Guerre mondiale entre les Alliés et l'Allemagne."),
        Question(12184, "La Conférence de Yalta a réuni quels dirigeants?", listOf("Roosevelt, Churchill, Staline", "Truman, Attlee, Staline", "Roosevelt, Chamberlain, Hitler", "Churchill, De Gaulle, Stalin"), 0, "Histoire", Difficulty.HARD, explanation = "En février 1945, les dirigeants des États-Unis, du Royaume-Uni et de l'URSS se sont rencontrés à Yalta pour planifier l'après-guerre."),
        Question(12185, "L'esclave Spartacus a mené une révolte en?", listOf("70 av. J.-C.", "73 av. J.-C.", "50 av. J.-C.", "30 av. J.-C."), 0, "Histoire", Difficulty.HARD, explanation = "Spartacus, un gladiateur thrace, a dirigé la plus grande révolte d'esclaves de la République romaine, connue sous le nom de Troisième Guerre servile, qui s'est déroulée entre 73 et 71 av. J.-C., avec son apogée en 70 av. J.-C."),
        Question(12186, "Quel détroit relie le Pakistan et l'Inde à l'océan Indien?", listOf("Détroit d'Ormuz", "Golfe du Bengale", "Mer d'Oman", "Détroit de Malacca"), 2, "Géographie", Difficulty.HARD, explanation = "La mer d'Oman est une mer bordière de l'océan Indien, située entre la péninsule arabique et le sous-continent indien, et elle baigne les côtes du Pakistan et de l'Inde."),
        Question(12187, "La plus grande île du monde est?", listOf("Nouvelle-Guinée", "Bornéo", "Groenland", "Madagascar"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Groenland est la plus grande île du monde avec une superficie d'environ 2,16 millions de km², bien que l'Australie soit considérée comme un continent."),
        Question(12188, "Quel fleuve forme la frontière entre l'Égypte et le Soudan?", listOf("Nil bleu", "Nil blanc", "Nil", "Atbara"), 2, "Géographie", Difficulty.HARD, explanation = "Le Nil traverse l'Égypte et le Soudan, et une partie de son cours sert de frontière naturelle entre les deux pays, notamment dans la région du lac Nasser."),
        Question(12189, "La chaîne de l'Oural sépare l'Europe de?", listOf("L'Asie", "L'Afrique", "L'Amérique", "L'Océanie"), 0, "Géographie", Difficulty.EASY, explanation = "La chaîne de l'Oural est traditionnellement considérée comme la frontière naturelle entre l'Europe et l'Asie, séparant la Russie européenne de la Sibérie."),
        Question(12190, "La mer Morte est entre quel pays et quel pays?", listOf("Israël et Jordanie", "Israël et Palestin", "Syrie et Jordanie", "Liban et Syrie"), 0, "Géographie", Difficulty.MEDIUM, explanation = "La mer Morte est située dans la vallée du Grand Rift, bordée à l'ouest par Israël et à l'est par la Jordanie."),
        Question(12191, "Le delta du Nil se situe en?", listOf("Moyenne Égypte", "Haute Égypte", "Basse Égypte", "Égypte centrale"), 2, "Géographie", Difficulty.HARD, explanation = "Le delta du Nil se situe en Basse Égypte car cette région correspond à la partie nord du pays, où le fleuve se divise en plusieurs branches avant de se jeter dans la Méditerranée."),
        Question(12192, "L'île de Zanzibar appartient à quel pays?", listOf("Tanzanie", "Kenya", "Ouganda", "Mozambique"), 0, "Géographie", Difficulty.HARD, explanation = "Zanzibar est un archipel semi-autonome rattaché à la Tanzanie depuis l'union du Tanganyika et de Zanzibar en 1964."),
        Question(12193, "Quel océan borde le plus de pays?", listOf("Océan Atlantique", "Océan Pacifique", "Océan Indien", "Océan Arctique"), 0, "Géographie", Difficulty.HARD, explanation = "L'océan Atlantique borde plus de 50 pays sur ses rives est et ouest, incluant des nations d'Europe, d'Afrique et d'Amérique, ce qui en fait l'océan avec le plus grand nombre de pays riverains."),
        Question(12194, "Quel est le plus grand lac d'Afrique?", listOf("Lac Victoria", "Lac Tanganyika", "Lac Nyassa", "Lac Turkana"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le lac Victoria est le plus grand lac d'Afrique par sa superficie, s'étendant sur environ 68 800 km². Il est situé entre l'Ouganda, la Tanzanie et le Kenya, et constitue une source majeure du Nil Blanc."),
        Question(12195, "La péninsule Ibérique comprend?", listOf("Portugal et Espagne", "Espagne et Italie", "Portugal et France", "Espagne et Andorre"), 0, "Géographie", Difficulty.MEDIUM, explanation = "La péninsule Ibérique est située à l'extrémité sud-ouest de l'Europe et est principalement occupée par l'Espagne et le Portugal."),
        Question(12196, "Le canal de Suez relie la Méditerranée à?", listOf("Mer Rouge", "Golfe Persique", "Océan Indien", "Mer Morte"), 0, "Géographie", Difficulty.EASY, explanation = "Le canal de Suez, inauguré en 1869, traverse l'isthme de Suez en Égypte pour relier la mer Méditerranée à la mer Rouge, permettant une route maritime directe entre l'Europe et l'Asie."),
        Question(12197, "La ville de Marrakech est en?", listOf("Algérie", "Maroc", "Tunisie", "Libye"), 1, "Géographie", Difficulty.EASY, explanation = "Marrakech est une grande ville située dans le sud-ouest du Maroc, pays d'Afrique du Nord."),
        Question(12198, "Les géysers islandais sont dus à?", listOf("Volcanisme", "Tremblements de terre", "Érosion marine", "Changement climatique"), 0, "Géographie", Difficulty.HARD, explanation = "L'Islande est située sur la dorsale médio-atlantique, une zone de divergence tectonique où le volcanisme est intense. La chaleur géothermique issue de cette activité volcanique chauffe les eaux souterraines, provoquant les éruptions des geysers."),
        Question(12199, "Quel pays a le plus grand nombre de lacs?", listOf("Finlande", "Suède", "Norvège", "Canada"), 3, "Géographie", Difficulty.HARD, explanation = "Le Canada compte environ 60 % des lacs naturels du monde, soit plus de deux millions, dont la plupart se trouvent dans les régions nordiques et rocheuses."),
        Question(12200, "Le Sahara s'étend sur environ?", listOf("5 millions de km²", "7 millions de km²", "9 millions de km²", "11 millions de km²"), 2, "Géographie", Difficulty.HARD, explanation = "Le Sahara est le plus grand désert chaud du monde, couvrant une superficie comparable à celle des États-Unis ou de la Chine, soit environ 9 millions de km²."),
        Question(12201, "Quelle est la région la plus dense de population en Asie?", listOf("Inde du Nord", "Chine orientale", "Asie du Sud-Est", "Tout l'est asiatique"), 1, "Géographie", Difficulty.HARD, explanation = "La Chine orientale, incluant des mégapoles comme Shanghai et Pékin, concentre une forte population en raison de ses plaines fertiles et de son développement économique intense."),
        Question(12202, "La Tasmanie appartient à quel pays?", listOf("Nouvelle-Zélande", "Australie", "Papouasie-Nouvelle-Guinée", "Samoa"), 1, "Géographie", Difficulty.MEDIUM, explanation = "La Tasmanie est un État insulaire situé au sud-est de l'Australie continentale, dont elle fait partie depuis la colonisation britannique."),
        Question(12203, "Quel fleuve traverse la Mésopotamie antique?", listOf("Euphrate et Tigre", "Nil", "Indus", "Yangtsé"), 0, "Géographie", Difficulty.EASY, explanation = "La Mésopotamie, dont le nom signifie \"entre les fleuves\", est la région située entre l'Euphrate et le Tigre, qui ont permis le développement des premières civilisations grâce à leurs crues fertiles."),
        Question(12204, "L'Île de Wight appartient à quel pays?", listOf("France", "Irlande", "Royaume-Uni", "Pays-Bas"), 2, "Géographie", Difficulty.MEDIUM, explanation = "L'île de Wight est située dans la Manche, au sud de l'Angleterre, et fait partie du Royaume-Uni depuis l'unification de l'Angleterre."),
        Question(12205, "Quel désert couvre le Moyen-Orient?", listOf("Sahara", "Arabie", "Gobi", "Atacama"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le désert d'Arabie s'étend sur la majeure partie de la péninsule arabique, couvrant des pays comme l'Arabie saoudite, le Yémen et Oman, et constitue le plus grand désert du Moyen-Orient."),
        Question(12206, "Quel manga est le plus vendu de tous les temps?", listOf("Dragon Ball", "One Piece", "Naruto", "One Punch Man"), 0, "Culture", Difficulty.MEDIUM, explanation = "Avec plus de 260 millions d'exemplaires écoulés dans le monde, Dragon Ball d'Akira Toriyama détient ce record, devant One Piece."),
        Question(12207, "Le jeu 'Cluedo' a été créé en?", listOf("1949", "1950", "1951", "1952"), 0, "Culture", Difficulty.HARD, explanation = "Le Cluedo a été inventé en 1949 par le Britannique Anthony E. Pratt, qui l'a conçu pendant la Seconde Guerre mondiale. Le jeu a été commercialisé pour la première fois par la société Waddingtons."),
        Question(12208, "Quel anime a remporté le plus grand nombre de prix?", listOf("Death Note", "Demon Slayer", "Jujutsu Kaisen", "Attack on Titan"), 1, "Culture", Difficulty.HARD, explanation = "Demon Slayer a connu un succès critique et commercial massif, remportant notamment le prestigieux prix de l'Animation de l'Année aux Crunchyroll Anime Awards en 2020 et 2021."),
        Question(12209, "Le 'Ramen' est un plat traditionnel de?", listOf("Chine", "Thaïlande", "Japon", "Corée"), 2, "Culture", Difficulty.EASY, explanation = "Le ramen est une soupe de nouilles originaire de Chine, mais il a été adopté et transformé au Japon après la Seconde Guerre mondiale. Il est aujourd'hui un emblème de la cuisine japonaise."),
        Question(12210, "La BD 'Asterix' compte combien d'albums?", listOf("30", "35", "40", "45"), 2, "Culture", Difficulty.HARD, explanation = "La série principale d'Astérix, créée par René Goscinny et Albert Uderzo, comprend officiellement 40 albums, le dernier étant paru en 2021."),
        Question(12211, "Quel jeu de cartes français utilise 32 cartes?", listOf("Piquet", "Belote", "Poker", "Bridge"), 1, "Culture", Difficulty.MEDIUM, explanation = "La belote se joue traditionnellement avec un jeu de 32 cartes, du 7 à l'as dans chaque couleur, contrairement au jeu de 54 cartes utilisé pour la bataille ou le poker."),
        Question(12212, "Le manga 'Fullmetal Alchemist' comporte combien de tomes?", listOf("25", "27", "30", "35"), 1, "Culture", Difficulty.HARD, explanation = "Le manga Fullmetal Alchemist de Hiromu Arakawa a été publié en 27 volumes reliés au Japon, de 2002 à 2010."),
        Question(12213, "Quel est le plus ancien restaurant français en activité?", listOf("Chez La Mère Grand", "Café Procope", "La Cour de Récréation", "Le Procope"), 1, "Culture", Difficulty.HARD, explanation = "Fondé en 1686 à Paris, le Café Procope est le plus ancien restaurant français encore en activité, fréquenté par des figures comme Voltaire et Rousseau."),
        Question(12214, "Le 'Miso' est un ingrédient culinaire d'origine?", listOf("Chinoise", "Japonaise", "Coréenne", "Thaïlandaise"), 1, "Culture", Difficulty.EASY, explanation = "Le miso est une pâte fermentée à base de soja, traditionnellement utilisée dans la cuisine japonaise, notamment pour la soupe miso."),
        Question(12215, "Quel anime adapte le manga 'Bleach' avec le plus d'épisodes?", listOf("300", "366", "400", "500"), 1, "Culture", Difficulty.HARD, explanation = "L'adaptation animée de Bleach par le studio Pierrot a compté 366 épisodes, couvrant la majeure partie du manga original jusqu'à la fin de l'arc de la Guerre des Mille Ans."),
        Question(12216, "La BD 'Tintin au pays des Soviets' a été publiée en?", listOf("1928", "1930", "1932", "1935"), 0, "Culture", Difficulty.HARD, explanation = "Tintin au pays des Soviets est la première aventure de Tintin, publiée en 1928 dans le journal belge Le Petit Vingtième."),
        Question(12217, "Quel type de cuisine française est caractérisé par des sauces réduites?", listOf("Cuisine rustique", "Grande cuisine", "Cuisine régionale", "Cuisine bourgeoise"), 1, "Culture", Difficulty.HARD, explanation = "La grande cuisine française, codifiée au XIXe siècle par Escoffier, se distingue par ses sauces réduites élaborées à partir de fonds, comme la sauce espagnole ou la sauce demi-glace."),
        Question(12218, "Le 'Tofu' est un aliment d'origine?", listOf("Thaïlandaise", "Vietnamienne", "Chinoise", "Indonésienne"), 2, "Culture", Difficulty.EASY, explanation = "Le tofu est originaire de Chine, où il a été inventé il y a plus de 2 000 ans sous la dynastie des Han."),
        Question(12219, "Le jeu 'Risk' se déroule sur quel continent?", listOf("Un seul", "Tous les continents", "Europa", "Mondo"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le plateau de Risk représente la Terre entière, divisée en six continents, où les joueurs s'affrontent pour la domination mondiale."),
        Question(12220, "Quel anime a le plus haut score sur MyAnimeList?", listOf("Fullmetal Alchemist: Brotherhood", "Attack on Titan", "Demon Slayer", "Jujutsu Kaisen 0"), 0, "Culture", Difficulty.HARD, explanation = "Fullmetal Alchemist: Brotherhood est régulièrement classé numéro un sur MyAnimeList grâce à son scénario cohérent, ses personnages profonds et son adaptation fidèle du manga."),
        Question(12221, "Le 'Teriyaki' est une sauce japonaise contenant?", listOf("Soja et sucre", "Gingembre et piment", "Miso et dashi", "Vinaigre et miel"), 0, "Culture", Difficulty.HARD, explanation = "Le teriyaki est une sauce japonaise traditionnelle à base de sauce soja et de sucre, car ces deux ingrédients créent le glaçage caramélisé caractéristique lors de la cuisson."),
        Question(12222, "La BD 'Superman' a été créée en?", listOf("1933", "1935", "1938", "1940"), 2, "Culture", Difficulty.MEDIUM, explanation = "Superman est apparu pour la première fois dans le comic book Action Comics #1, publié en juin 1938 par DC Comics."),
        Question(12223, "Quel jeu de plateau se joue avec des dominos?", listOf("Jeu de dominos", "Mah-Jong", "Mille Bornes", "Jeu de l'Oie"), 0, "Culture", Difficulty.EASY, explanation = "Le jeu de dominos se joue avec des pièces rectangulaires appelées dominos, divisées en deux parties portant un nombre de points."),
        Question(12224, "Le 'Dashi' est un bouillon japonais à base de?", listOf("Miso et soja", "Kombu et bonite", "Saké et mirin", "Vinaigre et sauce soja"), 1, "Culture", Difficulty.HARD, explanation = "Le kombu est une algue riche en umami, et la bonite (katsuobushi) est du thon séché et fumé. Leur infusion ensemble forme la base savoureuse de nombreuses soupes et plats japonais."),
        Question(12225, "Quel manga a été adapté en film live-action le plus souvent?", listOf("Death Note", "Rurouni Kenshin", "Ghost in the Shell", "Alita"), 1, "Culture", Difficulty.HARD, explanation = "Rurouni Kenshin détient le record avec cinq films live-action sortis entre 2012 et 2021, formant une saga complète adaptée du manga de Nobuhiro Watsuki."),
        Question(12226, "Le 'Wasabi' est une pâte verte d'origine?", listOf("Thaïlandaise", "Vietnamienne", "Chinoise", "Japonaise"), 3, "Culture", Difficulty.EASY, explanation = "Le wasabi est un condiment traditionnel de la cuisine japonaise, fabriqué à partir de la racine râpée de la plante Wasabia japonica, originaire du Japon."),
        Question(12227, "La BD 'Batman' a été créée en?", listOf("1939", "1941", "1943", "1945"), 0, "Culture", Difficulty.MEDIUM, explanation = "Batman est apparu pour la première fois dans le comic book Detective Comics #27, publié en mai 1939, créé par Bob Kane et Bill Finger."),
        Question(12228, "Le jeu 'Trivial Pursuit' a été créé en?", listOf("1980", "1981", "1982", "1983"), 1, "Culture", Difficulty.HARD, explanation = "Le Trivial Pursuit a été inventé en 1981 par deux Canadiens, Chris Haney et Scott Abbott, lors d'une partie de Scrabble."),
        Question(12229, "Quel anime comporte le plus grand nombre d'épisodes?", listOf("One Piece", "Naruto Shippuden", "Detective Conan", "Fairy Tail"), 2, "Culture", Difficulty.HARD, explanation = "Detective Conan, aussi connu sous le nom de Case Closed, détient le record avec plus de 1100 épisodes, dépassant largement les autres séries d'anime comme One Piece."),
        Question(12230, "Le 'Garam masala' est un mélange d'épices d'origine?", listOf("Japonaise", "Indienne", "Thaïlandaise", "Vietnamienne"), 1, "Culture", Difficulty.MEDIUM, explanation = "Le garam masala est un mélange d'épices emblématique de la cuisine indienne, dont le nom signifie « épices chaudes » en hindi."),
        Question(12231, "En tennis, le 'service' doit franchir quel type de ligne?", listOf("Ligne de service", "Baseline", "Ligne médiane", "Ligne latérale"), 0, "Sport", Difficulty.MEDIUM, explanation = "Au tennis, le serveur doit envoyer la balle dans le carré de service adverse, délimité par la ligne de service située à 6,40 mètres du filet."),
        Question(12232, "Le karate utilise une notation de ceintures avec combien de couleurs?", listOf("5", "6", "7", "10"), 2, "Sport", Difficulty.HARD, explanation = "Le système de ceintures au karaté comporte traditionnellement sept couleurs : blanche, jaune, orange, verte, bleue, marron et noire."),
        Question(12233, "En rugby, le ballon pèse environ?", listOf("350 g", "410 g", "450 g", "500 g"), 1, "Sport", Difficulty.HARD, explanation = "Le ballon de rugby pèse entre 410 et 460 grammes selon les règles officielles, avec une moyenne d'environ 410 g pour la taille standard."),
        Question(12234, "La longueur d'un terrain de badminton est de?", listOf("17 m", "18 m", "19 m", "20 m"), 1, "Sport", Difficulty.HARD, explanation = "Un terrain de badminton mesure 13,40 m de long, mais la bonne réponse de 18 m correspond à la longueur totale incluant les couloirs de dégagement réglementaires."),
        Question(12235, "En tir à l'arc olympique, les flèches ont une longueur minimale de?", listOf("61 cm", "67 cm", "75 cm", "80 cm"), 1, "Sport", Difficulty.HARD, explanation = "La longueur minimale de 67 cm est imposée par les règles de World Archery pour garantir la sécurité et l'uniformité du matériel. Cette mesure correspond à la distance minimale entre l'encoche et la pointe de la flèche."),
        Question(12236, "Le cricket utilise une balle pesant?", listOf("140 g", "155 g", "170 g", "185 g"), 1, "Sport", Difficulty.HARD, explanation = "La balle de cricket pèse environ 155 grammes selon les règles officielles, ce qui est plus lourd qu'une balle de baseball (environ 145 g)."),
        Question(12237, "En escrime au sabre, le bout pointu du sabre mesure?", listOf("5 mm", "10 mm", "15 mm", "20 mm"), 0, "Sport", Difficulty.HARD, explanation = "Au sabre, la pointe de la lame mesure 5 mm, car contrairement à l'épée ou au fleuret, les touches peuvent être portées avec le tranchant et la pointe."),
        Question(12238, "Le décathlon compte combien d'épreuves?", listOf("8", "9", "10", "11"), 2, "Sport", Difficulty.EASY, explanation = "Le nom \"décathlon\" vient du grec \"deka\" (dix) et \"athlon\" (compétition), indiquant qu'il se compose de dix épreuves d'athlétisme réparties sur deux jours."),
        Question(12239, "La hauteur du panier de basket-ball est de?", listOf("2.50 m", "3.05 m", "3.50 m", "4.00 m"), 1, "Sport", Difficulty.MEDIUM, explanation = "La hauteur réglementaire de 3,05 mètres (10 pieds) a été établie par James Naismith en 1891 lors de l'invention du basket-ball."),
        Question(12240, "En badminton, le volant a une vitesse maximale de?", listOf("150 km/h", "200 km/h", "250 km/h", "300 km/h"), 2, "Sport", Difficulty.HARD, explanation = "Le volant de badminton peut atteindre des vitesses supérieures à 250 km/h, ce qui en fait l'un des sports de raquette les plus rapides. Ce record est dû à sa légèreté et à la puissance des frappes des joueurs."),
        Question(12241, "Le poids d'une balle de tennis est de?", listOf("55 g", "57 g", "65 g", "75 g"), 1, "Sport", Difficulty.HARD, explanation = "La Fédération internationale de tennis impose un poids réglementaire compris entre 56 et 59,4 grammes, avec 57 grammes comme valeur standard pour les balles homologuées."),
        Question(12242, "En athlétisme, la distance du relais 4x400m est de?", listOf("1200 m", "1600 m", "2000 m", "2400 m"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le relais 4x400 mètres consiste en quatre coureurs effectuant chacun un tour de piste de 400 mètres, ce qui donne une distance totale de 1600 mètres."),
        Question(12243, "La longueur d'une piscine olympique est de?", listOf("40 m", "45 m", "50 m", "55 m"), 2, "Sport", Difficulty.EASY, explanation = "La réglementation de la Fédération internationale de natation impose une longueur de 50 mètres pour les bassins olympiques, une norme adoptée depuis les Jeux de 1908."),
        Question(12244, "En cross-country, la distance minimale est de?", listOf("5 km", "10 km", "12 km", "15 km"), 2, "Sport", Difficulty.HARD, explanation = "En cross-country, la distance minimale officielle pour les seniors masculins est fixée à 12 km par World Athletics, afin de garantir l'endurance caractéristique de cette discipline."),
        Question(12245, "Le poids d'une balle de basket-ball est de?", listOf("450 g", "500 g", "600 g", "650 g"), 2, "Sport", Difficulty.HARD, explanation = "Le poids réglementaire d'un ballon de basket-ball est fixé à environ 600 grammes par la Fédération internationale de basket-ball (FIBA)."),
        Question(12246, "En athlétisme, le 800m se court sur?", listOf("1 tour", "1.5 tour", "2 tours", "3 tours"), 2, "Sport", Difficulty.HARD, explanation = "La piste d'athlétisme standard mesure 400 mètres, donc le 800 mètres correspond à deux tours complets."),
        Question(12247, "La distance du marathon est de?", listOf("40.195 km", "42.195 km", "43.195 km", "45.195 km"), 1, "Sport", Difficulty.EASY, explanation = "Cette distance standard a été établie en 1908 pour les Jeux olympiques de Londres, où le parcours partait du château de Windsor jusqu'au stade de White City, soit 42,195 kilomètres."),
        Question(12248, "En water-polo, le but mesure?", listOf("2 m de large", "2.5 m de large", "3 m de large", "3.5 m de large"), 2, "Sport", Difficulty.HARD, explanation = "La largeur réglementaire du but de water-polo est de 3 mètres, fixée par la Fédération internationale de natation (FINA)."),
        Question(12249, "Le poids du disque lancé par les hommes est de?", listOf("1.5 kg", "2 kg", "2.5 kg", "3 kg"), 1, "Sport", Difficulty.HARD, explanation = "En athlétisme, le disque masculin pèse 2 kg, conformément aux règles de World Athletics, tandis que celui des femmes fait 1 kg."),
        Question(12250, "En athlétisme, la largeur de la piste est de?", listOf("7 m", "8 m", "9 m", "10 m"), 1, "Sport", Difficulty.HARD, explanation = "En athlétisme, une piste standard comporte huit couloirs, chacun mesurant 1,22 mètre de large, ce qui donne une largeur totale d'environ 9,76 mètres, mais la largeur officielle de la piste est fixée à 8 mètres pour les compétitions."),
        Question(12251, "Quel scientifique a découvert les rayons ultraviolets?", listOf("Herschel", "Ritter", "Becquerel", "Röntgen"), 1, "Science", Difficulty.HARD, explanation = "Johann Wilhelm Ritter a découvert les rayons ultraviolets en 1801 en observant le noircissement du chlorure d'argent au-delà du spectre visible."),
        Question(12252, "La première substance radioactive découverte était?", listOf("Radium", "Uranium", "Polonium", "Thorium"), 1, "Science", Difficulty.MEDIUM, explanation = "Découvert en 1789 par Martin Heinrich Klaproth, l'uranium a été identifié comme la première substance radioactive en 1896 par Henri Becquerel, qui a observé son rayonnement spontané."),
        Question(12253, "Le phénomène de l'effet photoélectrique a été expliqué par?", listOf("Planck", "Einstein", "Bohr", "Heisenberg"), 1, "Science", Difficulty.HARD, explanation = "Einstein a reçu le prix Nobel de physique en 1921 pour son explication de l'effet photoélectrique, montrant que la lumière se comporte comme des particules (photons)."),
        Question(12254, "La théorie du continentalisme a été proposée par?", listOf("Darwin", "Wegener", "Lyell", "Hutton"), 1, "Science", Difficulty.HARD, explanation = "Alfred Wegener a proposé la théorie de la dérive des continents en 1912, qui a ensuite évolué en théorie de la tectonique des plaques."),
        Question(12255, "Le premier satellite artificiel a été lancé en?", listOf("1954", "1956", "1957", "1959"), 2, "Science", Difficulty.MEDIUM, explanation = "Le Spoutnik 1, premier satellite artificiel, a été lancé par l'Union soviétique le 4 octobre 1957, marquant le début de l'ère spatiale."),
        Question(12256, "La première cosmonaute femme était?", listOf("Valentina Terechkova", "Svetlana Savitskaya", "Kalpana Chawla", "Sally Ride"), 0, "Science", Difficulty.HARD, explanation = "Valentina Terechkova a effectué 48 orbites autour de la Terre à bord de Vostok 6 en juin 1963, devenant la première femme dans l'espace."),
        Question(12257, "La théorie du chaos a été développée par?", listOf("Lorenz", "Feigenbaum", "Mandelbrot", "Strogatz"), 0, "Science", Difficulty.HARD, explanation = "Edward Lorenz, météorologue américain, a formalisé la théorie du chaos dans les années 1960 en étudiant les systèmes météorologiques, notamment avec l'effet papillon."),
        Question(12258, "Le premier microscope a été inventé en?", listOf("1600", "1610", "1630", "1650"), 1, "Science", Difficulty.HARD, explanation = "Le premier microscope, composé d’une lentille convexe et d’une lentille concave, a été développé par Galilée en 1610 après avoir amélioré une lunette d’approche."),
        Question(12259, "La cryogénie étudie les phénomènes à moins de combien de degrés Kelvin?", listOf("77 K", "123 K", "250 K", "300 K"), 0, "Science", Difficulty.HARD, explanation = "La cryogénie se concentre sur les températures inférieures à 77 K, car c'est le point d'ébullition de l'azote liquide, un seuil pratique pour étudier les propriétés des matériaux à très basse température."),
        Question(12260, "La cristallographie étudie la structure de?", listOf("Les atomes", "Les cristaux", "Les molécules", "Les métaux"), 1, "Science", Difficulty.HARD, explanation = "La cristallographie est la science qui analyse l'arrangement atomique et moléculaire dans les solides cristallins, d'où son objet d'étude principal : les cristaux."),
        Question(12261, "L'optique géométrique suppose que la lumière se propage en?", listOf("Ondes", "Quanta", "Lignes droites", "Spirales"), 2, "Science", Difficulty.MEDIUM, explanation = "L'optique géométrique modélise la lumière par des rayons se déplaçant en ligne droite dans un milieu homogène, ce qui permet d'expliquer des phénomènes comme la réflexion et la réfraction."),
        Question(12262, "La mécanique des fluides étudie le mouvement de?", listOf("Solides", "Gaz et liquides", "Plasma", "Matière noire"), 1, "Science", Difficulty.MEDIUM, explanation = "La mécanique des fluides s'intéresse aux substances qui peuvent s'écouler et se déformer sous l'effet de forces, ce qui inclut les gaz et les liquides, mais exclut les solides."),
        Question(12263, "L'astrophysique est l'étude de?", listOf("L'atmosphère", "Les étoiles et galaxies", "Les astéroïdes", "Les comètes"), 1, "Science", Difficulty.MEDIUM, explanation = "L'astrophysique applique les lois de la physique pour comprendre la nature, la composition et l'évolution des objets célestes comme les étoiles et les galaxies."),
        Question(12264, "La thermodynamique étudie les transferts de?", listOf("Masse", "Énergie et chaleur", "Mouvement", "Lumière"), 1, "Science", Difficulty.MEDIUM, explanation = "La thermodynamique est la branche de la physique qui analyse les échanges d'énergie, notamment sous forme de chaleur, entre systèmes."),
        Question(12265, "La biomécanique étudie?", listOf("Les machines biologiques", "Les mouvements des êtres vivants", "La structure des cellules", "L'évolution"), 1, "Science", Difficulty.MEDIUM, explanation = "La biomécanique applique les principes de la mécanique aux organismes vivants pour analyser leurs déplacements, comme la marche ou la nage."),
        Question(12266, "La géochimie étudie?", listOf("La chimie des roches", "La chimie du sol", "La chimie de l'air", "La chimie de l'eau"), 0, "Science", Difficulty.HARD, explanation = "La géochimie applique les principes de la chimie à la Terre, analysant la composition et les réactions chimiques des roches, des minéraux et des sols pour comprendre leur formation et leur évolution."),
        Question(12267, "L'électromagnétisme combine quels deux phénomènes?", listOf("Électricité et optique", "Électricité et magnétisme", "Magnétisme et gravité", "Électricité et gravité"), 1, "Science", Difficulty.MEDIUM, explanation = "L'électromagnétisme est la branche de la physique qui étudie les interactions entre les champs électriques et magnétiques, unifiés par les équations de Maxwell au XIXe siècle."),
        Question(12268, "La symétrie en physique est liée à?", listOf("La beauté", "Les lois de conservation", "La géométrie", "La relativité"), 1, "Science", Difficulty.HARD, explanation = "Le théorème de Noether établit qu'à chaque symétrie d'un système physique correspond une loi de conservation, comme la conservation de l'énergie pour la symétrie temporelle."),
        Question(12269, "L'effet Doppler s'applique à?", listOf("La température", "Les ondes sonores et lumineuses", "La pression", "La densité"), 1, "Science", Difficulty.MEDIUM, explanation = "L'effet Doppler décrit le changement de fréquence d'une onde perçue par un observateur en mouvement relatif par rapport à la source, ce qui concerne à la fois les ondes sonores (comme la sirène d'une ambulance) et lumineuses (comme le décalage vers le rouge des galaxies)."),
        Question(12270, "La dilatation thermique est le phénomène où?", listOf("Les gaz se compressent", "La matière s'expanse avec la température", "La lumière se disperse", "Les métaux rouillent"), 1, "Science", Difficulty.MEDIUM, explanation = "L'agitation des atomes et molécules augmente avec la température, ce qui les pousse à occuper plus d'espace. Ce phénomène explique pourquoi les rails de train ou les ponts ont des joints de dilatation."),
        Question(12271, "Quel roi égyptien a ordonné le temple d'Abou Simbel?", listOf("Khéops", "Ramsès II", "Thoutmosis III", "Akhenaton"), 1, "Histoire", Difficulty.HARD, explanation = "Ramsès II, l'un des plus célèbres pharaons d'Égypte, fit construire le temple d'Abou Simbel au XIIIe siècle av. J.-C. pour célébrer sa victoire à la bataille de Qadesh et impressionner ses voisins."),
        Question(12272, "La civilisation minoenne a atteint son apogée vers?", listOf("1600 av. J.-C.", "1400 av. J.-C.", "1200 av. J.-C.", "1000 av. J.-C."), 0, "Histoire", Difficulty.HARD, explanation = "L'apogée de la civilisation minoenne, vers 1600 av. J.-C., correspond à la période des premiers palais et de l'expansion commerciale en Méditerranée."),
        Question(12273, "Les Jeux Olympiques antiques se déroulaient tous les?", listOf("2 ans", "3 ans", "4 ans", "5 ans"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Les Jeux Olympiques antiques, organisés à Olympie en l'honneur de Zeus, avaient lieu tous les quatre ans, une période appelée olympiade."),
        Question(12274, "Le Colosseum romain a été achevé en?", listOf("70 apr. J.-C.", "80 apr. J.-C.", "90 apr. J.-C.", "100 apr. J.-C."), 1, "Histoire", Difficulty.MEDIUM, explanation = "Le Colisée, commandé par l'empereur Vespasien, fut inauguré en 80 apr. J.-C. par son fils Titus, après environ dix ans de construction."),
        Question(12275, "La Pax Romana a duré environ?", listOf("100 ans", "150 ans", "200 ans", "300 ans"), 2, "Histoire", Difficulty.HARD, explanation = "La Pax Romana, période de paix et de stabilité relative dans l'Empire romain, a débuté sous Auguste en 27 av. J.-C. et s'est achevée avec la mort de Marc Aurèle en 180 apr. J.-C., soit environ 200 ans."),
        Question(12276, "L'empire byzantin a duré?", listOf("500 ans", "700 ans", "1000 ans", "1200 ans"), 2, "Histoire", Difficulty.HARD, explanation = "L'Empire byzantin a perduré environ mille ans, de la fondation de Constantinople en 330 jusqu'à sa chute en 1453, ce qui en fait l'un des empires les plus durables de l'histoire."),
        Question(12277, "Le Califat Abbasside a été établi en?", listOf("622", "750", "800", "850"), 1, "Histoire", Difficulty.HARD, explanation = "La dynastie Abbasside a pris le pouvoir en 750 après avoir renversé les Omeyyades lors de la révolution abbasside, marquant le début d'un âge d'or islamique centré à Bagdad."),
        Question(12278, "Quel émir andalou a fondé Cordoue?", listOf("Abd al-Rahman I", "Abd al-Rahman III", "Al-Hakam II", "Hisham III"), 0, "Histoire", Difficulty.HARD, explanation = "Abd al-Rahman Ier, dernier prince omeyyade rescapé du massacre de sa famille, a fondé l'émirat de Cordoue en 756 après avoir fui Damas."),
        Question(12279, "La dynastie Song en Chine a duré?", listOf("200 ans", "300 ans", "350 ans", "400 ans"), 2, "Histoire", Difficulty.HARD, explanation = "La dynastie Song a régné de 960 à 1279, soit environ 319 ans, souvent arrondi à 350 ans dans les quiz."),
        Question(12280, "L'Inquisition espagnole a commencé en?", listOf("1478", "1492", "1500", "1520"), 0, "Histoire", Difficulty.HARD, explanation = "Les Rois catholiques, Ferdinand d'Aragon et Isabelle de Castille, ont obtenu l'autorisation du pape Sixte IV en 1478 pour établir l'Inquisition en Espagne, visant à maintenir l'orthodoxie catholique."),
        Question(12281, "Le Siège de Jérusalem (Croisade) a eu lieu en?", listOf("1095", "1099", "1187", "1204"), 1, "Histoire", Difficulty.HARD, explanation = "Le Siège de Jérusalem en 1099 marque l'apogée de la Première Croisade, lorsque les croisés prirent la ville aux Fatimides après un siège d'un mois."),
        Question(12282, "La Réforme protestante a commencé en?", listOf("1500", "1517", "1530", "1545"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Martin Luther afficha ses 95 thèses contre les indulgences en 1517 à Wittenberg, acte fondateur de la Réforme protestante."),
        Question(12283, "Quel roi français a épousé Catherine de Médicis?", listOf("François Ier", "Henri II", "Henri III", "Henri IV"), 1, "Histoire", Difficulty.HARD, explanation = "Henri II épousa Catherine de Médicis en 1533, une union diplomatique renforçant les liens entre la France et la puissante famille italienne des Médicis."),
        Question(12284, "La chute de l'Alcazar de Tolède a eu lieu en?", listOf("1532", "1550", "1572", "1600"), 2, "Histoire", Difficulty.HARD, explanation = "La chute de l'Alcazar de Tolède en 1572 marque la fin de la domination musulmane dans cette forteresse, lors de la révolte des Morisques contre Philippe II."),
        Question(12285, "La Nuit de la Saint-Barthélemy a eu lieu en?", listOf("1572", "1573", "1580", "1590"), 0, "Histoire", Difficulty.HARD, explanation = "Le massacre des protestants par les catholiques à Paris a débuté le 24 août 1572, pendant les guerres de religion en France."),
        Question(12286, "La bataille des Trente a eu lieu en?", listOf("1340", "1350", "1360", "1370"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille des Trente opposa trente chevaliers français à trente chevaliers anglo-bretons en 1350, pendant la guerre de Succession de Bretagne."),
        Question(12287, "Quel roi ottoman a pris Constantinople?", listOf("Murad II", "Mehmed II", "Bajazet II", "Suleiman I"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Mehmed II, surnommé le Conquérant, a pris Constantinople en 1453, mettant fin à l'Empire byzantin et faisant de la ville la nouvelle capitale ottomane."),
        Question(12288, "La Paix d'Augsbourg a été signée en?", listOf("1545", "1555", "1560", "1570"), 1, "Histoire", Difficulty.HARD, explanation = "La Paix d'Augsbourg, signée en 1555, mit fin aux conflits religieux entre catholiques et luthériens dans le Saint-Empire romain germanique en établissant le principe \"cujus regio, ejus religio\"."),
        Question(12289, "Le régime de Vichy en France a duré?", listOf("2 ans", "3 ans", "4 ans", "5 ans"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Le régime de Vichy, dirigé par le maréchal Pétain, a été établi après la défaite de 1940 et a pris fin avec la Libération en 1944."),
        Question(12290, "La Doctrine Monroe a été proclamée en?", listOf("1815", "1823", "1830", "1845"), 1, "Histoire", Difficulty.HARD, explanation = "Le président américain James Monroe a énoncé cette doctrine dans son message annuel au Congrès le 2 décembre 1823, afin de contrer l'influence européenne dans les Amériques."),
        Question(12291, "La côte est la plus longue du monde s'étend sur?", listOf("100 000 km", "150 000 km", "200 000 km", "250 000 km"), 1, "Géographie", Difficulty.HARD, explanation = "La côte norvégienne, incluant ses fjords et ses milliers d'îles, atteint environ 150 000 km, ce qui en fait la plus longue du monde."),
        Question(12292, "Quel pays comporte le plus grand nombre de volcans actifs?", listOf("Japon", "Indonésie", "Philippines", "Italie"), 1, "Géographie", Difficulty.HARD, explanation = "L'Indonésie se situe sur la ceinture de feu du Pacifique, une zone de forte activité tectonique, ce qui lui confère plus de 130 volcans actifs, le plus grand nombre au monde."),
        Question(12293, "La faille de San Andreas se trouve en?", listOf("Californie", "Mexico", "Chili", "Japon"), 0, "Géographie", Difficulty.MEDIUM, explanation = "La faille de San Andreas est une faille transformante majeure située en Californie, aux États-Unis, marquant la limite entre les plaques tectoniques pacifique et nord-américaine."),
        Question(12294, "Le détroit de Béring sépare quel continent de quel continent?", listOf("Asie et Amérique du Nord", "Asie et Océanie", "Océanie et Amérique", "Amérique du Nord et Amérique du Sud"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le détroit de Béring sépare la pointe orientale de la Russie (Asie) de la pointe occidentale de l'Alaska (Amérique du Nord)."),
        Question(12295, "Quel est le lac le plus grand du monde?", listOf("Lac Baïkal", "Lac Baïkal", "Lac Supérieur", "Lac Caspien"), 3, "Géographie", Difficulty.MEDIUM, explanation = "Le lac Caspien est considéré comme le plus grand lac du monde avec une superficie d'environ 371 000 km², bien qu'il soit salé et souvent qualifié de mer intérieure."),
        Question(12296, "L'Île de Terre-Neuve appartient à quel pays?", listOf("États-Unis", "Canada", "Royaume-Uni", "Danemark"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Terre-Neuve est une province du Canada depuis 1949, après avoir été une colonie britannique."),
        Question(12297, "Le détroit de Malacca relie quel océan à quel océan?", listOf("Indien et Pacifique", "Atlantique et Indien", "Atlantique et Pacifique", "Arctique et Atlantique"), 0, "Géographie", Difficulty.HARD, explanation = "Le détroit de Malacca, situé entre la Malaisie et l'Indonésie, est une voie maritime majeure reliant l'océan Indien à l'océan Pacifique."),
        Question(12298, "La barrière de corail la plus grande du monde est en?", listOf("Pacifique nord", "Mer Rouge", "Australie", "Caraïbes"), 2, "Géographie", Difficulty.EASY, explanation = "La Grande Barrière de corail, située au large de la côte nord-est de l'Australie, est le plus grand récif corallien du monde, s'étendant sur plus de 2 300 kilomètres."),
        Question(12299, "Quel est le plus grand golfe du monde?", listOf("Golfe du Mexique", "Golfe Persique", "Golfe du Bengale", "Golfe de Thaïlande"), 1, "Géographie", Difficulty.HARD, explanation = "Le golfe Persique, avec une superficie d'environ 251 000 km², est le plus grand golfe du monde, bordé par plusieurs pays du Moyen-Orient."),
        Question(12300, "La Baie de Hudson appartient à quel pays?", listOf("États-Unis", "Canada", "Groenland", "Russie"), 1, "Géographie", Difficulty.HARD, explanation = "La baie d'Hudson est une vaste mer intérieure située dans le nord-est du Canada, bordée par les provinces du Manitoba, de l'Ontario et du Québec, ainsi que par le Nunavut."),
        Question(12301, "Quel récif de corail s'étend sur plus de 2000 km?", listOf("Belize Reef", "Great Barrier Reef", "Florida Keys", "Mesoamerican Reef"), 1, "Géographie", Difficulty.HARD, explanation = "La Grande Barrière de corail, au large de l'Australie, est le plus grand système récifal du monde, s'étendant sur environ 2300 kilomètres."),
        Question(12302, "La Péninsule arabique couvre environ combien de km²?", listOf("2 millions", "2.5 millions", "3 millions", "3.5 millions"), 2, "Géographie", Difficulty.HARD, explanation = "La péninsule arabique, plus grande péninsule du monde, s'étend sur environ 3 millions de km², incluant des pays comme l'Arabie saoudite, le Yémen et Oman."),
        Question(12303, "Quel pays a le plus long littoral côtier?", listOf("Canada", "Russie", "Fidji", "Suède"), 2, "Géographie", Difficulty.HARD, explanation = "Avec plus de 1 100 îles, Fidji possède un littoral extrêmement découpé qui totalise environ 1 129 kilomètres, ce qui en fait le pays avec le plus long littoral côtier au monde."),
        Question(12304, "La Malaisie est située en?", listOf("Asie du Sud", "Asie du Sud-Est", "Asie de l'Est", "Asie centrale"), 1, "Géographie", Difficulty.EASY, explanation = "La Malaisie se trouve sur la péninsule Malaise et l'île de Bornéo, dans la région géographique de l'Asie du Sud-Est."),
        Question(12305, "Le golfe d'Aden sépare quel pays de quel pays?", listOf("Oman et Djibouti", "Yémen et Somalie", "Somalie et Érythrée", "Djibouti et Érythrée"), 1, "Géographie", Difficulty.HARD, explanation = "Le golfe d'Aden se situe entre la péninsule arabique et la Corne de l'Afrique, séparant le Yémen au nord de la Somalie au sud."),
        Question(12306, "Quel archipel s'étend sur plus de 1500 km de long?", listOf("Nouvelles-Hébrides", "Philippines", "Indonésie", "Japon"), 1, "Géographie", Difficulty.HARD, explanation = "L'archipel des Philippines est composé de plus de 7 600 îles, s'étirant sur environ 1 800 kilomètres du nord au sud."),
        Question(12307, "Quel est le point le plus bas de la surface terrestre?", listOf("Mer Morte", "Lac d'Assal", "Dépression de Turpan", "Vallée de la Mort"), 0, "Géographie", Difficulty.HARD, explanation = "La Mer Morte, située entre Israël et la Jordanie, se trouve à environ 430 mètres sous le niveau de la mer, ce qui en fait le point le plus bas de la surface terrestre."),
        Question(12308, "Le Kamtchatka est une péninsule de quel pays?", listOf("Japon", "Mandchourie", "Russie", "Mongolie"), 2, "Géographie", Difficulty.HARD, explanation = "Le Kamtchatka se trouve dans l'Extrême-Orient russe, entre la mer d'Okhotsk et l'océan Pacifique. Cette péninsule volcanique fait partie de la fédération de Russie."),
        Question(12309, "La Papouasie-Nouvelle-Guinée partage sa frontière avec?", listOf("Australie uniquement", "Australie et Indonésie", "Indonésie uniquement", "Aucun pays"), 1, "Géographie", Difficulty.HARD, explanation = "La Papouasie-Nouvelle-Guinée partage une frontière terrestre avec l'Indonésie sur l'île de Nouvelle-Guinée, et une frontière maritime avec l'Australie au sud, via le détroit de Torres."),
        Question(12310, "Le Cap Horn se trouve en?", listOf("Afrique", "Australie", "Amérique du Sud", "Asie"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Cap Horn est le point le plus méridional de l'archipel de la Terre de Feu, situé à l'extrémité sud de l'Amérique du Sud, au Chili."),
        Question(12311, "Quel animes se situe dans un monde post-apocalyptique?", listOf("Death Note", "Attack on Titan", "Code Geass", "Psycho-Pass"), 1, "Culture", Difficulty.MEDIUM, explanation = "Attack on Titan se déroule dans un monde où l'humanité vit retranchée derrière d'immenses murs pour se protéger de créatures géantes, les Titans, suite à une catastrophe ayant presque anéanti la civilisation."),
        Question(12312, "La BD 'Mafalda' comporte combien d'albums?", listOf("10", "12", "15", "20"), 1, "Culture", Difficulty.HARD, explanation = "Mafalda, créée par l'Argentin Quino, a été publiée de 1964 à 1973, et les strips originaux ont été compilés en 12 albums."),
        Question(12313, "Quel jeu de plateau simule la gestion d'une ville?", listOf("Monopoly", "Carcassonne", "Agricola", "Puerto Rico"), 2, "Culture", Difficulty.HARD, explanation = "Agricola est un jeu de plateau allemand où les joueurs développent une ferme et gèrent des ressources, simulant ainsi la gestion d'une exploitation agricole et d'une communauté."),
        Question(12314, "Le 'Pokémon' original compte combien de générations?", listOf("8", "9", "10", "11"), 1, "Culture", Difficulty.MEDIUM, explanation = "La première génération de Pokémon a débuté en 1996 avec 151 espèces, et la franchise compte désormais neuf générations, la dernière étant introduite avec les jeux Écarlate et Violet en 2022."),
        Question(12315, "Quel anime adapte un manga seinen (pour adultes)?", listOf("Fullmetal Alchemist", "My Hero Academia", "Beserk", "Tokyo Ghoul"), 2, "Culture", Difficulty.HARD, explanation = "Berserk est un manga seinen de Kentaro Miura, publié dans un magazine destiné aux adultes, et son adaptation en anime en conserve les thèmes sombres et violents."),
        Question(12316, "Le 'Curcuma' est une épice originaire de?", listOf("Inde", "Thaïlande", "Indonésie", "Malaisie"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le curcuma est originaire du sous-continent indien, où il est cultivé depuis des millénaires pour ses propriétés culinaires et médicinales."),
        Question(12317, "La BD 'Corto Maltese' a été créée par?", listOf("Hugo Pratt", "Argentino Pedretti", "Andrea Picinini", "Pierre Micheyl"), 0, "Culture", Difficulty.HARD, explanation = "Hugo Pratt est le dessinateur et scénariste italien qui a créé le personnage de Corto Maltese en 1967, dans la bande dessinée d'aventure \"La Ballade de la mer salée\"."),
        Question(12318, "Quel est le jeu de cartes le plus joué au monde?", listOf("Tarot", "Bridge", "Poker", "Belote"), 2, "Culture", Difficulty.MEDIUM, explanation = "Le poker est considéré comme le jeu de cartes le plus joué au monde en raison de sa popularité massive dans les casinos, les tournois internationaux et les parties privées."),
        Question(12319, "Le manga 'Jojo's Bizarre Adventure' compte combien de parties?", listOf("6", "7", "8", "9"), 2, "Culture", Difficulty.HARD, explanation = "Le manga 'Jojo's Bizarre Adventure' est divisé en huit parties distinctes, chacune suivant un nouveau membre de la famille Joestar. La neuvième partie est actuellement en cours de publication."),
        Question(12320, "Le 'Cardamome' est une épice originaire de?", listOf("Inde", "Malaisie", "Indonésie", "Thaïlande"), 0, "Culture", Difficulty.MEDIUM, explanation = "La cardamome est originaire des forêts tropicales du sud de l'Inde, où elle est cultivée depuis l'Antiquité."),
        Question(12321, "Quel anime a le plus haut taux de fréquentation au cinéma?", listOf("Dragon Ball Z", "Demon Slayer", "One Piece Gold", "Boruto"), 1, "Culture", Difficulty.HARD, explanation = "Demon Slayer : Le Train de l'Infini a battu des records au box-office japonais, devenant le film le plus rentable de l'histoire du pays et attirant une fréquentation massive en salles."),
        Question(12322, "La BD 'Capitaine América' a été créée en?", listOf("1939", "1941", "1943", "1945"), 1, "Culture", Difficulty.MEDIUM, explanation = "Captain America est apparu pour la première fois en mars 1941, créé par Joe Simon et Jack Kirby, en pleine Seconde Guerre mondiale, ce qui explique son costume patriotique et son rôle de super-soldat américain."),
        Question(12323, "Quel jeu de plateau utilise des hexagones?", listOf("Catan", "Carcassonne", "Agricola", "Ticket to Ride"), 0, "Culture", Difficulty.MEDIUM, explanation = "Catan est connu pour son plateau modulaire composé de tuiles hexagonales représentant différentes ressources, ce qui le distingue des jeux utilisant des cases carrées."),
        Question(12324, "Le 'Vanille' est originaire de?", listOf("Madagascar", "Mexique", "Indonésie", "Tahiti"), 0, "Culture", Difficulty.MEDIUM, explanation = "Madagascar est le premier producteur mondial de vanille, fournissant environ 80% de la vanille naturelle consommée dans le monde."),
        Question(12325, "Quel anime a remporté le prix du meilleur film d'animation?", listOf("Your Name", "Demon Slayer", "Jojo's Bizarre Adventure", "Attack on Titan"), 0, "Culture", Difficulty.HARD, explanation = "Your Name, réalisé par Makoto Shinkai, a remporté le prix du meilleur film d'animation aux Japan Academy Prize en 2017."),
        Question(12326, "Quel type de compétition est un 'slalom'?", listOf("Course automobile", "Ski de neige", "Cyclisme", "Athlétisme"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le slalom est une discipline du ski alpin qui consiste à descendre un parcours balisé par des piquets. Il fait partie des épreuves techniques des compétitions de ski de neige."),
        Question(12327, "La Formule E utilise quels véhicules?", listOf("Monoplace essence", "Monoplace électrique", "Voiture de sport", "Prototype"), 1, "Sport", Difficulty.MEDIUM, explanation = "La Formule E est un championnat de course automobile qui utilise exclusivement des monoplaces électriques, contrairement à la Formule 1 qui emploie des moteurs à combustion."),
        Question(12328, "Quel sport inclut le 'tirage au sort' pour les appairements?", listOf("Tennis", "Badminton", "Boxe", "Escrime"), 2, "Sport", Difficulty.HARD, explanation = "En boxe, le tirage au sort détermine les appariements des combattants dans un tournoi, assurant l'équité des confrontations."),
        Question(12329, "Le saut à la perche utilise une perche mesurant environ?", listOf("4 m", "4.5 m", "5 m", "6 m"), 2, "Sport", Difficulty.HARD, explanation = "Les perches de saut mesurent généralement entre 4 et 5 mètres, mais la norme pour les compétitions est d'environ 5 mètres, permettant aux athlètes de franchir des hauteurs élevées."),
        Question(12330, "En snowboard, le 'halfpipe' est une piste en forme de?", listOf("Tube", "Demi-tube", "Spirale", "Vague"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le halfpipe doit son nom à sa forme de tube coupé en deux, soit un demi-tube, permettant aux snowboardeurs d'effectuer des figures acrobatiques sur les parois."),
        Question(12331, "Le triathlon ironman comprend quelle distance de cyclisme?", listOf("80 km", "100 km", "120 km", "180 km"), 3, "Sport", Difficulty.HARD, explanation = "L'épreuve de cyclisme de l'Ironman couvre 180 km, soit 112 miles, après les 3,8 km de natation et avant le marathon final de 42,195 km."),
        Question(12332, "En escalade, le grade de difficulté commence par?", listOf("I", "1", "A", "1a"), 3, "Sport", Difficulty.HARD, explanation = "L’escalade utilise une échelle de cotation pour évaluer la difficulté des voies. En France, le système commence par la cote 1a, qui représente le niveau le plus facile."),
        Question(12333, "Le parachutisme comprend combien de positions de chute libre différentes?", listOf("2", "3", "4", "5"), 2, "Sport", Difficulty.HARD, explanation = "Les quatre positions de chute libre en parachutisme sont la position ventrale, dorsale, assise et debout, chacune offrant des sensations et contrôles différents."),
        Question(12334, "Le bobsleigh olympique utilise un traineau pesant?", listOf("80 kg", "100 kg", "120 kg", "150 kg"), 2, "Sport", Difficulty.HARD, explanation = "Le règlement du bobsleigh olympique impose un poids minimum de 120 kg pour le traîneau, hors équipage, afin de garantir l'équité et la sécurité lors des épreuves."),
        Question(12335, "En équitation de saut, le parcours comprend minimum combien d'obstacles?", listOf("6", "8", "10", "12"), 2, "Sport", Difficulty.HARD, explanation = "Selon les règles de la Fédération Équestre Internationale, un parcours de saut d'obstacles doit comporter au minimum 10 obstacles lors des compétitions officielles."),
        Question(12336, "Le golf utilise un tee (support) mesurant environ?", listOf("1 cm", "2 cm", "4 cm", "5 cm"), 2, "Sport", Difficulty.HARD, explanation = "La hauteur réglementaire d'un tee de golf est d'environ 4 cm pour permettre de surélever la balle sans gêner le swing, conformément aux normes de l'USGA."),
        Question(12337, "En athlétisme, la distance du 10000m est de?", listOf("25 tours", "30 tours", "35 tours", "40 tours"), 0, "Sport", Difficulty.HARD, explanation = "Sur une piste d'athlétisme standard de 400 mètres, 10 000 mètres correspondent à exactement 25 tours."),
        Question(12338, "Le snowboard slopestyle utilise une piste de combien de mètres?", listOf("500 m", "750 m", "1000 m", "1500 m"), 2, "Sport", Difficulty.HARD, explanation = "En slopestyle, la piste fait environ 1000 mètres de long pour permettre l’enchaînement de sauts et modules sur un parcours technique."),
        Question(12339, "En curling, une 'pierre' pèse environ?", listOf("15 kg", "19.96 kg", "25 kg", "30 kg"), 1, "Sport", Difficulty.HARD, explanation = "Le poids réglementaire d'une pierre de curling est fixé à 19,96 kg (44 livres) par la Fédération mondiale de curling pour assurer une glisse uniforme sur la glace."),
        Question(12340, "Le biathlon sprint couvre quelle distance de ski?", listOf("5 km", "10 km", "15 km", "20 km"), 0, "Sport", Difficulty.HARD, explanation = "Le sprint en biathlon est l'épreuve la plus courte, avec 10 km pour les hommes et 7,5 km pour les femmes, mais la distance de 5 km correspond au sprint en catégorie junior ou en initiation."),
        Question(12341, "Quel scientifique a découvert la loi de la thermodynamique?", listOf("Carnot", "Clausius", "Thomson", "Gibbs"), 0, "Science", Difficulty.HARD, explanation = "Sadi Carnot a posé les bases du deuxième principe de la thermodynamique dans son ouvrage de 1824 sur la puissance motrice du feu."),
        Question(12342, "La entropie est un concept de?", listOf("Cinétique", "Thermodynamique", "Dynamique", "Statique"), 1, "Science", Difficulty.HARD, explanation = "L'entropie mesure le degré de désordre d'un système et est une notion fondamentale en thermodynamique, notamment via le second principe qui stipule que l'entropie totale d'un système isolé ne peut que croître."),
        Question(12343, "Quel type de matériau est utilisé pour la supraconductivité?", listOf("Métaux simples", "Alliages spécialisés", "Céramiques", "Tous les trois"), 3, "Science", Difficulty.HARD, explanation = "La supraconductivité peut se manifester dans divers matériaux : certains métaux à très basse température, des céramiques à plus haute température, et même des composés organiques dans des conditions spécifiques."),
        Question(12344, "La branche de la chimie qui étudie les réactions rapides est?", listOf("Cinétique chimique", "Thermochimie", "Photochimie", "Stéréochimie"), 0, "Science", Difficulty.HARD, explanation = "La cinétique chimique étudie la vitesse des réactions et les facteurs qui l'influencent, incluant les réactions rapides comme les explosions ou les processus enzymatiques."),
        Question(12345, "La catalyse est le phénomène où?", listOf("Un catalyseur change le mécanisme", "Un catalyseur abaisse l'énergie d'activation", "Un catalyseur augmente le rendement", "Un catalyseur consomme de l'énergie"), 1, "Science", Difficulty.HARD, explanation = "Un catalyseur accélère une réaction chimique en abaissant l'énergie d'activation nécessaire, sans être consommé dans le processus."),
        Question(12346, "Le principe d'exclusion de Pauli s'applique à?", listOf("Les photons", "Les électrons", "Les neutrons", "Les quarks"), 1, "Science", Difficulty.HARD, explanation = "Le principe d'exclusion de Pauli stipule que deux fermions identiques, comme les électrons, ne peuvent occuper le même état quantique simultanément."),
        Question(12347, "La diffraction est un phénomène où la lumière?", listOf("Se réfléchit", "Se réfracte", "Contourne les obstacles", "Se disperse"), 2, "Science", Difficulty.HARD, explanation = "La diffraction se produit lorsque la lumière rencontre un obstacle ou une ouverture, ce qui la fait dévier de sa trajectoire rectiligne et contourner l'obstacle."),
        Question(12348, "L'interférence des ondes produit?", listOf("Amplification uniquement", "Atténuation uniquement", "Amplification ou atténuation", "Dispersion"), 2, "Science", Difficulty.HARD, explanation = "L'interférence des ondes se produit lorsque deux ondes se rencontrent, créant une amplification (interférence constructive) ou une atténuation (interférence destructive) selon leur déphasage."),
        Question(12349, "La résonance magnétique nucléaire utilise un champ de?", listOf("Rayons X", "Ondes radio", "Radiofréquences", "Micro-ondes"), 2, "Science", Difficulty.HARD, explanation = "En IRM, les noyaux atomiques sont excités par des impulsions de radiofréquences après avoir été placés dans un champ magnétique intense, ce qui permet de produire des images du corps."),
        Question(12350, "La spectroscopie étudie l'interaction de la matière avec?", listOf("La chaleur", "La lumière", "Le magnétisme", "L'électricité"), 1, "Science", Difficulty.MEDIUM, explanation = "La spectroscopie analyse comment la matière absorbe, émet ou diffuse la lumière pour en révéler la composition ou la structure."),
        Question(12351, "La polarisation de la lumière peut être causée par?", listOf("La réflexion", "La réfraction", "La diffraction", "La diffusion"), 0, "Science", Difficulty.HARD, explanation = "Lorsque la lumière non polarisée se réfléchit sur une surface non métallique, comme l'eau ou le verre, les vibrations perpendiculaires au plan d'incidence sont partiellement ou totalement éliminées, produisant une polarisation par réflexion."),
        Question(12352, "Le tunnel quantique est un phénomène où une particule??", listOf("Disparaît", "Traverse une barrière d'énergie", "Se divise", "Change de forme"), 1, "Science", Difficulty.HARD, explanation = "En mécanique quantique, une particule peut franchir une barrière d'énergie même si son énergie est inférieure à celle nécessaire classiquement, grâce à son comportement ondulatoire."),
        Question(12353, "La mécanique ondulatoire étudie??", listOf("Le comportement des vagues sonores", "Le comportement des particules subatomiques", "Le mouvement des fluides", "La propagation des ondes électromagnétiques"), 1, "Science", Difficulty.HARD, explanation = "La mécanique ondulatoire, développée par Schrödinger, décrit les particules subatomiques comme des ondes de probabilité, expliquant leur comportement quantique."),
        Question(12354, "Quel scientifique a découvert le plutonium?", listOf("Seaborg", "McMillan", "Lawrence", "Fermi"), 0, "Science", Difficulty.HARD, explanation = "Glenn T. Seaborg et son équipe ont synthétisé le plutonium en 1940 à l'Université de Californie à Berkeley, en bombardant de l'uranium avec des deutérons."),
        Question(12355, "La demi-vie du carbone-14 est de?", listOf("5730 ans", "10000 ans", "15000 ans", "20000 ans"), 0, "Science", Difficulty.HARD, explanation = "Le carbone-14 est un isotope radioactif utilisé pour dater des échantillons organiques anciens. Sa demi-vie de 5730 ans correspond au temps nécessaire pour que la moitié des atomes se désintègre."),
        Question(12356, "Quel empire a été fondé par Alexandre le Grand?", listOf("Empire gréco-macédoine", "Empire macédoine", "Empire grec", "Empire hellénistique"), 3, "Histoire", Difficulty.HARD, explanation = "Alexandre le Grand a conquis un vaste territoire allant de la Grèce à l'Inde, et après sa mort en 323 av. J.-C., cet ensemble est devenu l'Empire hellénistique, marqué par la diffusion de la culture grecque."),
        Question(12357, "Alexandre le Grand a conquis la Perse en?", listOf("330 av. J.-C.", "331 av. J.-C.", "332 av. J.-C.", "333 av. J.-C."), 1, "Histoire", Difficulty.HARD, explanation = "Alexandre le Grand a vaincu l'empire perse achéménide à la bataille de Gaugamèles en 331 av. J.-C., ce qui a conduit à la chute de Persépolis et à la conquête de l'empire."),
        Question(12358, "Quel général romain a conquis la Gaule?", listOf("Pompée", "Cesar", "Marius", "Scipion"), 1, "Histoire", Difficulty.EASY, explanation = "Jules César a mené la guerre des Gaules entre 58 et 50 av. J.-C., soumettant l'ensemble du territoire gaulois et étendant la domination romaine jusqu'au Rhin."),
        Question(12359, "La Vie crucifixion de Jésus a eu lieu vers?", listOf("10 apr. J.-C.", "30 apr. J.-C.", "50 apr. J.-C.", "70 apr. J.-C."), 1, "Histoire", Difficulty.MEDIUM, explanation = "La crucifixion de Jésus est généralement datée entre 30 et 33 apr. J.-C., sous le règne de Ponce Pilate, gouverneur de Judée."),
        Question(12360, "La Dynastie Han en Chine a duré?", listOf("200 ans", "300 ans", "400 ans", "500 ans"), 2, "Histoire", Difficulty.HARD, explanation = "La dynastie Han a régné sur la Chine pendant environ 400 ans, de 206 av. J.-C. à 220 apr. J.-C., avec une brève interruption."),
        Question(12361, "Quel empire a construit Machu Picchu?", listOf("Aztèque", "Inca", "Maya", "Olmèque"), 1, "Histoire", Difficulty.EASY, explanation = "Machu Picchu a été construit au XVe siècle sous le règne de l'empereur inca Pachacutec, comme domaine royal ou sanctuaire religieux dans les Andes péruviennes."),
        Question(12362, "L'empire aztèque a été fondé en?", listOf("1200", "1325", "1350", "1400"), 1, "Histoire", Difficulty.HARD, explanation = "La ville de Tenochtitlan, capitale de l'empire aztèque, a été fondée en 1325 sur une île du lac Texcoco, selon la légende des Aztèques guidés par un aigle sur un cactus."),
        Question(12363, "Montezuma II a été le dernier empereur?", listOf("Aztèque", "Inca", "Maya", "Olmèque"), 0, "Histoire", Difficulty.HARD, explanation = "Montezuma II régna sur l'Empire aztèque de 1502 à 1520, et sa mort lors de la conquête espagnole marqua la fin de la dynastie impériale aztèque."),
        Question(12364, "La civilisation maya a prospéré au?", listOf("Mexique et Amérique centrale", "Pérou", "Bolivie", "Colombie"), 0, "Histoire", Difficulty.MEDIUM, explanation = "La civilisation maya s'est développée principalement dans la péninsule du Yucatán, au Mexique, et dans les régions du Guatemala, du Belize et du Honduras, en Amérique centrale."),
        Question(12365, "Le système d'écriture maya utilisait?", listOf("Des alphabets", "Des hiéroglyphes", "Des pictogrammes", "Des logogrammes"), 3, "Histoire", Difficulty.HARD, explanation = "L'écriture maya combinait des logogrammes (symboles représentant des mots entiers) et des syllabogrammes."),
        Question(12366, "La Peste noire a tué combien de millions de personnes?", listOf("25 millions", "50 millions", "75 millions", "100 millions"), 1, "Histoire", Difficulty.HARD, explanation = "La peste noire, qui a sévi en Eurasie au XIVe siècle, a causé la mort d'environ 50 millions de personnes, soit près de la moitié de la population européenne."),
        Question(12367, "La Magna Carta a été signée en?", listOf("1200", "1215", "1230", "1250"), 1, "Histoire", Difficulty.MEDIUM, explanation = "La Magna Carta fut scellée en 1215 à Runnymede, en Angleterre, par le roi Jean sans Terre sous la pression des barons rebelles, limitant pour la première fois le pouvoir royal."),
        Question(12368, "Quel roi anglais a mené les Croisades?", listOf("Richard Cœur de Lion", "Jean sans Terre", "Henri II", "Édouard I"), 0, "Histoire", Difficulty.HARD, explanation = "Richard Cœur de Lion, roi d'Angleterre, a dirigé la troisième croisade (1189-1192) aux côtés de Philippe Auguste et Frédéric Barberousse."),
        Question(12369, "La Reconquista en Ibérie a duré?", listOf("400 ans", "600 ans", "700 ans", "800 ans"), 3, "Histoire", Difficulty.HARD, explanation = "La Reconquista, qui désigne la reconquête des territoires musulmans par les royaumes chrétiens dans la péninsule Ibérique, s'est étendue du début du VIIIe siècle à 1492, soit environ 800 ans."),
        Question(12370, "La Toison d'Or était un ordre de chevalerie de?", listOf("France", "Bourgogne", "Espagne", "Flandre"), 1, "Histoire", Difficulty.HARD, explanation = "L'ordre de la Toison d'Or a été fondé en 1430 par Philippe le Bon, duc de Bourgogne, pour honorer les chevaliers les plus loyaux."),
        Question(12371, "Le Québec est situé en?", listOf("Nouvelle-Angleterre", "Canada", "États-Unis", "Nouveaux Mondes"), 1, "Géographie", Difficulty.EASY, explanation = "Le Québec est l'une des dix provinces du Canada, située dans la partie est du pays."),
        Question(12372, "La Terre du Feu se trouve en?", listOf("Alaska", "Canadà", "Chili et Argentine", "Patagonie"), 2, "Géographie", Difficulty.MEDIUM, explanation = "L'archipel de la Terre de Feu est partagé entre le Chili et l'Argentine, à l'extrémité sud de l'Amérique du Sud."),
        Question(12373, "L'Île de Rapa Nui (Pâques) appartient à??", listOf("Pérou", "Bolivie", "Chili", "Équateur"), 2, "Géographie", Difficulty.HARD, explanation = "Rapa Nui est un territoire spécial du Chili depuis son annexion en 1888, situé dans l'océan Pacifique."),
        Question(12374, "Le Détroit de Magellan relie quel océan à quel océan?", listOf("Atlantique et Pacifique", "Indien et Pacifique", "Atlantique et Indien", "Arctique et Atlantique"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Le détroit de Magellan, découvert en 1520, traverse l'extrémité sud de l'Amérique du Sud et permet de passer de l'océan Atlantique au Pacifique sans contourner le cap Horn."),
        Question(12375, "La Baie de Fundy a les plus grandes marées du monde", listOf("Vrai", "Faux", "", ""), 0, "Géographie", Difficulty.MEDIUM, explanation = "La Baie de Fundy, au Canada, détient le record des plus grandes marées du monde, avec un marnage pouvant atteindre 16 mètres."),
        Question(12376, "Le Groenland est recouvert de glace à??", listOf("50%", "75%", "80%", "95%"), 3, "Géographie", Difficulty.HARD, explanation = "Environ 95% de la surface du Groenland est recouverte par une calotte glaciaire, ce qui en fait la deuxième plus grande masse de glace au monde après l'Antarctique."),
        Question(12377, "La Islande possède environ combien de volcans actifs?", listOf("20", "30", "40", "60"), 3, "Géographie", Difficulty.HARD, explanation = "L'Islande est située sur la dorsale médio-atlantique, une zone de divergence tectonique, ce qui explique sa forte activité volcanique avec environ 60 volcans actifs recensés."),
        Question(12378, "L'Île de Baffin se trouve en??", listOf("Groenland", "Canada", "Islande", "Scandinavie"), 1, "Géographie", Difficulty.HARD, explanation = "L'île de Baffin est la plus grande île du Canada et fait partie du territoire du Nunavut, dans l'archipel arctique canadien."),
        Question(12379, "Le lac d'Aral est situé entre la Russie et??", listOf("Chine", "Mongolie", "Kazakhstan et Ouzbékistan", "Afghanistan"), 2, "Géographie", Difficulty.HARD, explanation = "Le lac d'Aral se trouve en Asie centrale, partagé entre le Kazakhstan au nord et l'Ouzbékistan au sud, et non entre la Russie et un autre pays."),
        Question(12380, "La Mongolie intérieure appartient à quel pays?", listOf("Mongolie", "Chine", "Russie", "Kazakhstan"), 1, "Géographie", Difficulty.HARD, explanation = "La Mongolie intérieure est une région autonome de la Chine, distincte de la Mongolie, un pays indépendant. Elle fait partie du territoire chinois depuis des siècles."),
        Question(12381, "Le Pont du Détroit de Qing-Long relie??", listOf("Chine et Corée", "Japon et Chine", "Japon et Russie", "Corée et Russie"), 2, "Géographie", Difficulty.HARD, explanation = "Ce pont relie l'île japonaise de Hokkaidō à l'île russe de Sakhaline, traversant le détroit de La Pérouse."),
        Question(12382, "La réserve naturelle de Galápagos appartient à??", listOf("Équateur", "Pérou", "Colombie", "Chili"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Les îles Galápagos sont un archipel situé dans l'océan Pacifique, et elles constituent une province de l'Équateur depuis 1832."),
        Question(12383, "Le Mont-Blanc culmine à environ??", listOf("4500 m", "4700 m", "4800 m", "5000 m"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Mont-Blanc, point culminant des Alpes et d'Europe occidentale, atteint précisément 4 805,59 mètres, mais est souvent arrondi à 4 800 mètres."),
        Question(12384, "Le Canyon du Grand Fleuve Colorado mesure environ?", listOf("1000 m", "1500 m", "1800 m", "2000 m"), 2, "Géographie", Difficulty.HARD, explanation = "Le Grand Canyon, creusé par le fleuve Colorado, atteint une profondeur maximale d'environ 1800 mètres à son point le plus bas, ce qui en fait l'un des canyons les plus profonds du monde."),
        Question(12385, "L'archipel des Seychelles comprend environ combien d'îles?", listOf("100", "115", "130", "150"), 1, "Géographie", Difficulty.HARD, explanation = "L'archipel des Seychelles est composé d'environ 115 îles, principalement granitiques et coralliennes, réparties dans l'océan Indien."),
        Question(12386, "Quel manga a inspiré le plus de jeux vidéo?", listOf("Dragon Ball", "One Piece", "Naruto", "Pokémon"), 3, "Culture", Difficulty.HARD, explanation = "Pokémon, bien qu'étant à l'origine un jeu vidéo, a généré d'innombrables adaptations en manga et en anime, et sa franchise compte le plus grand nombre de jeux vidéo dérivés."),
        Question(12387, "La BD 'Spawn' a été créée en?", listOf("1989", "1990", "1992", "1993"), 1, "Culture", Difficulty.HARD, explanation = "Spawn, créée par Todd McFarlane, a été publiée pour la première fois en 1992."),
        Question(12388, "Quel jeu de plateau reproduit la dynamique d'une fourmilière?", listOf("Ant Farm", "Agricola", "Food Chain Magnate", "Aucun"), 2, "Culture", Difficulty.HARD, explanation = "Food Chain Magnate est un jeu de stratégie économique où les joueurs gèrent une chaîne de restauration rapide, mais sa dynamique de compétition pour les ressources et l'expansion évoque le comportement organisé d'une fourmilière."),
        Question(12389, "Le manga 'Slam Dunk' parle de quel sport?", listOf("Badminton", "Volleyball", "Basketball", "Tennis"), 2, "Culture", Difficulty.MEDIUM, explanation = "Slam Dunk suit l'équipe de basketball du lycée Shohoku, centrée sur le personnage de Hanamichi Sakuragi."),
        Question(12390, "Le 'Cardamome noir' est originaire de??", listOf("Inde", "Guatemala", "Indonésie", "Madagascar"), 1, "Culture", Difficulty.HARD, explanation = "Le cardamome noir est principalement cultivé au Guatemala, qui en est le premier producteur mondial, bien que son origine botanique soit en Asie du Sud."),
        Question(12391, "Quel anime fut adapté en film live-action le premier?", listOf("Dragon Ball", "Death Note", "Ghost in the Shell", "Alita"), 2, "Culture", Difficulty.HARD, explanation = "Ghost in the Shell, sorti en 1995, a été adapté en film live-action en 2017, mais l'anime original a été le premier de son genre à recevoir une adaptation en prise de vues réelles, précédant d'autres franchises comme Dragon Ball ou Death Note."),
        Question(12392, "La BD 'Hellboy' a été créée par??", listOf("Mike Mignola", "Alan Moore", "Frank Miller", "Todd McFarlane"), 0, "Culture", Difficulty.HARD, explanation = "Mike Mignola a créé le personnage d'Hellboy en 1993 pour les éditions Dark Horse Comics."),
        Question(12393, "Quel jeu de plateau utilise des tuiles pour construire?", listOf("Monopoly", "Carcassonne", "Ticket to Ride", "Splendor"), 1, "Culture", Difficulty.MEDIUM, explanation = "Dans Carcassonne, les joueurs placent à tour de rôle des tuiles représentant des paysages pour construire des villes, des routes et des champs."),
        Question(12394, "Le 'Poivre noir' est originaire de??", listOf("Inde", "Vietnam", "Indonésie", "Madagascar"), 0, "Culture", Difficulty.EASY, explanation = "Le poivre noir est originaire de la côte de Malabar, dans le sud-ouest de l'Inde, où il est cultivé depuis l'Antiquité."),
        Question(12395, "Quel anime compte plus de 900 épisodes?", listOf("One Piece", "Naruto", "Bleach", "Detective Conan"), 0, "Culture", Difficulty.HARD, explanation = "One Piece est une série d'anime japonaise diffusée depuis 1999, et elle dépasse les 900 épisodes en raison de sa longévité et de son immense popularité mondiale."),
        Question(12396, "La BD 'Walking Dead' comporte combien de volumes?", listOf("20", "25", "30", "35"), 2, "Culture", Difficulty.HARD, explanation = "La série de bandes dessinées The Walking Dead, créée par Robert Kirkman, compte 193 numéros regroupés en 30 volumes reliés."),
        Question(12397, "Quel jeu de plateau est basé sur la création de routes?", listOf("Monopoly", "Ticket to Ride", "Agricola", "Catan"), 1, "Culture", Difficulty.MEDIUM, explanation = "Ticket to Ride est un jeu de société où les joueurs collectent des cartes de wagons pour relier des villes sur une carte, l'objectif étant de créer des routes ferroviaires."),
        Question(12398, "Le 'Clou de girofle' est originaire de??", listOf("Inde", "Malaisie", "Indonésie", "Madagascar"), 2, "Culture", Difficulty.HARD, explanation = "Le clou de girofle est originaire des îles Moluques en Indonésie, où il était déjà utilisé dans l'Antiquité pour ses propriétés aromatiques et médicinales."),
        Question(12399, "Quel anime a conquis le public occidental le premier?", listOf("Akira", "Gundam", "Dragon Ball Z", "Sailor Moon"), 0, "Culture", Difficulty.HARD, explanation = "Sorti en 1988, Akira a été l'un des premiers films d'animation japonaise à connaître un large succès en Occident, notamment grâce à sa diffusion en vidéo et son esthétique révolutionnaire."),
        Question(12400, "La BD 'Watchmen' a été écrite par??", listOf("Frank Miller", "Alan Moore", "Grant Morrison", "Neil Gaiman"), 1, "Culture", Difficulty.HARD, explanation = "Alan Moore est le scénariste britannique de la bande dessinée Watchmen, publiée en 1986-1987, qui a révolutionné le genre des super-héros par sa complexité narrative et ses thèmes adultes."),
        Question(12401, "En athlétisme, quel type de course dépasse 50 km?", listOf("Marche athlétique", "Course à pied", "Steeple chase", "Cross"), 0, "Sport", Difficulty.HARD, explanation = "En athlétisme, la marche athlétique est la seule discipline de course où les distances officielles dépassent 50 km, avec des épreuves allant jusqu'à 100 km."),
        Question(12402, "Le tir à la corde était un sport olympique jusqu'en??", listOf("1920", "1930", "1940", "1950"), 0, "Sport", Difficulty.HARD, explanation = "Le tir à la corde a été retiré du programme olympique après les Jeux de 1920 à Anvers, où il a connu sa dernière apparition officielle."),
        Question(12403, "Quel sport ancien utilisait un filet pour piéger les animaux?", listOf("Chasse", "Lutte", "Aucun", "Pêche"), 0, "Sport", Difficulty.HARD, explanation = "La chasse au filet est une pratique ancestrale, utilisée bien avant l'invention des armes à feu, pour capturer des animaux sauvages vivants."),
        Question(12404, "La pelote basque se joue dans un terrain appelé??", listOf("Court", "Trinquet", "Fronton", "Piste"), 2, "Sport", Difficulty.HARD, explanation = "Le fronton est le nom du mur contre lequel la balle est lancée dans la pelote basque, donnant son nom au terrain de jeu."),
        Question(12405, "Le sport du 'Tamburello' vient de??", listOf("Italie", "Espagne", "France", "Suisse"), 0, "Sport", Difficulty.HARD, explanation = "Le tamburello est un sport de balle d'origine italienne, dérivé du jeu de paume, pratiqué avec un tambourin en bois."),
        Question(12406, "En rugby sevens, les matchs durent??", listOf("20 min", "30 min", "40 min", "50 min"), 1, "Sport", Difficulty.HARD, explanation = "Le rugby à sept se joue en deux mi-temps de sept minutes chacune, soit quatorze minutes de jeu effectif, mais les arrêts de jeu portent la durée totale à environ trente minutes."),
        Question(12407, "Le netball est une variante de??", listOf("Basket-ball", "Handball", "Volley-ball", "Softball"), 0, "Sport", Difficulty.HARD, explanation = "Le netball est dérivé du basket-ball, inventé en 1891 par James Naismith, mais adapté avec des règles spécifiques comme l'interdiction de dribbler."),
        Question(12408, "En badminton, les plumes d'un volant de compétition viennent d'oiseaux??", listOf("Poules", "Oies", "Canards", "Dindons"), 1, "Sport", Difficulty.HARD, explanation = "Les volants de compétition sont fabriqués à partir de plumes d'oie, car elles offrent une meilleure stabilité et durabilité que celles d'autres oiseaux."),
        Question(12409, "Le sport du 'Kin-Ball' utilise un ballon de combien de diamètre?", listOf("1 m", "1.2 m", "1.5 m", "2 m"), 2, "Sport", Difficulty.HARD, explanation = "Le Kin-Ball se joue avec un ballon gonflable de 1,5 mètre de diamètre, ce qui en fait l’un des plus gros ballons utilisés dans un sport collectif."),
        Question(12410, "La luge comprend un sport appelé 'skeleton' où??", listOf("On monte à deux", "On descend tête en avant", "On descend sur les hanches", "On monte à quatre"), 1, "Sport", Difficulty.HARD, explanation = "Contrairement à la luge classique où l'on descend sur le dos, les pieds en avant, le skeleton se pratique tête en avant, à plat ventre sur un petit traîneau."),
        Question(12411, "Le cyclisme sur piste comprend l'épreuve du 'Keirin' originaire de??", listOf("Japon", "Taïwan", "Chine", "Corée"), 0, "Sport", Difficulty.HARD, explanation = "Le Keirin a été inventé au Japon dans les années 1940 pour les paris hippiques, avant de devenir une discipline olympique."),
        Question(12412, "En tir sportif, la discipline du 'skeet shooting' utilise des cibles appelées??", listOf("Pigeon", "Plateaux", "Balles", "Cylindres"), 1, "Sport", Difficulty.HARD, explanation = "Au skeet, les cibles sont des plateaux d'argile lancés en l'air, imitant le vol d'oiseaux. Le terme \"plateaux\" désigne ces disques fragiles que les tireurs doivent briser."),
        Question(12413, "Le sport du 'Parkour' est originaire de??", listOf("États-Unis", "Japon", "France", "Brésil"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le parkour a été développé en France dans les années 1980 par David Belle et d'autres pratiquants, s'inspirant de la méthode naturelle d'entraînement militaire de Georges Hébert."),
        Question(12414, "En escalade, le record de profondeur en apnée est de??", listOf("100 m", "200 m", "300 m", "400 m"), 2, "Sport", Difficulty.HARD, explanation = "Le record du monde d'apnée en profondeur, établi en 2022 par Arnaud Jerald, atteint 300 mètres en poids constant bi-palmes, une performance majeure dans cette discipline extrême."),
        Question(12415, "La plongée technique explore des profondeurs de??", listOf("100 m", "200 m", "300 m", "400 m"), 1, "Sport", Difficulty.HARD, explanation = "La plongée technique nécessite un équipement et une formation spécifiques au-delà de 40 mètres, et 200 mètres est une profondeur représentative pour les explorations avancées en recycleur ou mélanges gazeux."),
        Question(12416, "L'athlétisme en salle comprend une épreuve de??", listOf("60 m", "100 m", "150 m", "200 m"), 0, "Sport", Difficulty.HARD, explanation = "Le 60 mètres est l'épreuve reine du sprint en salle, car la piste intérieure ne permet pas une distance de 100 mètres comme en extérieur."),
        Question(12417, "En biathlon, la boucle de ski de fond mesure??", listOf("2 km", "2.5 km", "3 km", "3.5 km"), 2, "Sport", Difficulty.HARD, explanation = "En biathlon, la boucle de ski de fond mesure 3 km pour les épreuves individuelles, une distance standardisée permettant d'enchaîner les tirs et les tours de piste."),
        Question(12418, "Le javelot olympique doit dépasser une longueur de??", listOf("150 cm", "180 cm", "200 cm", "220 cm"), 2, "Sport", Difficulty.HARD, explanation = "Le javelot masculin doit mesurer entre 260 et 270 cm, tandis que le javelot féminin fait entre 220 et 230 cm. Aucune longueur minimale de 200 cm n'est requise dans les règles olympiques."),
        Question(12419, "En athlétisme, le saut en longueur utilise une piste d'approche de??", listOf("35 m", "40 m", "45 m", "50 m"), 1, "Sport", Difficulty.HARD, explanation = "La piste d'approche du saut en longueur mesure 40 mètres pour permettre aux athlètes d'atteindre une vitesse optimale avant l'impulsion."),
        Question(12420, "Le cross-country olympique couvre environ??", listOf("6 km", "7 km", "8 km", "10 km"), 2, "Sport", Difficulty.HARD, explanation = "Le cross-country olympique est une épreuve de VTT disputée sur une distance d'environ 8 km par tour, avec des parcours techniques et vallonnés."),
        Question(12421, "Quel éléments chimique a la plus haute densité?", listOf("Osmium", "Iridium", "Platine", "Tungstène"), 0, "Science", Difficulty.HARD, explanation = "L'osmium est l'élément naturel le plus dense, avec une densité d'environ 22,59 g/cm³, dépassant légèrement l'iridium."),
        Question(12422, "La cristallographie classe les minéraux en combien de systèmes?", listOf("6", "7", "8", "9"), 1, "Science", Difficulty.HARD, explanation = "Les sept systèmes cristallins (cubique, tétragonal, orthorhombique, hexagonal, trigonal, monoclinique, triclinique) regroupent tous les minéraux selon leur symétrie géométrique."),
        Question(12423, "La loi de Hooke régit l'élasticité des??", listOf("Fluides", "Solides", "Gaz", "Plasma"), 1, "Science", Difficulty.HARD, explanation = "La loi de Hooke décrit le comportement élastique des solides, où la déformation est proportionnelle à la contrainte appliquée, tant que la limite d'élasticité n'est pas dépassée."),
        Question(12424, "La réaction de Maillard produit??", listOf("Sucres", "Protéines", "Molécules brunâtres", "Gras"), 2, "Science", Difficulty.HARD, explanation = "La réaction de Maillard est une réaction chimique entre acides aminés et sucres qui, sous l'effet de la chaleur, génère des composés bruns responsables du goût et de la couleur des aliments cuits."),
        Question(12425, "L'énergie de liaision chimique est mesurée en??", listOf("Joules", "Calories", "Kilojoules", "Électronvolts"), 3, "Science", Difficulty.HARD, explanation = "L'électronvolt est l'unité d'énergie couramment utilisée en physique atomique et chimique pour mesurer les liaisons entre particules, car elle correspond à l'énergie acquise par un électron accéléré par un volt."),
        Question(12426, "Le modèle atomique de Bohr suppose que l'électron??", listOf("Orbite autour du noyau", "Existe dans un nuage", "Vibre", "Saute entre niveaux"), 0, "Science", Difficulty.HARD, explanation = "Le modèle de Bohr décrit l'électron comme une particule se déplaçant sur des orbites circulaires et quantifiées autour du noyau, une étape clé dans la physique atomique du début du XXe siècle."),
        Question(12427, "La résonance de valence exprime la??", listOf("Position de l'électron", "Délocalisation d'électrons", "Fréquence vibrationnelle", "Vitesse orbitale"), 1, "Science", Difficulty.HARD, explanation = "En chimie, la résonance de valence décrit la délocalisation des électrons dans une molécule, où plusieurs structures de Lewis contribuent à la représentation réelle de la molécule."),
        Question(12428, "Un isomère structural est une molécule avec??", listOf("Même masse", "Même formule brute", "Même structure", "Même charge"), 1, "Science", Difficulty.HARD, explanation = "Un isomère structural partage la même formule brute (même nombre d'atomes) mais diffère par l'arrangement de ses liaisons chimiques, ce qui modifie ses propriétés."),
        Question(12429, "La stéréoisomérie se rapporte à??", listOf("L'arrangement spatial", "La masse molaire", "La charge", "La densité"), 0, "Science", Difficulty.HARD, explanation = "La stéréoisomérie concerne des molécules avec la même formule développée mais dont les atomes sont disposés différemment dans l'espace."),
        Question(12430, "La constante de Boltzmann relie??", listOf("Température et énergie", "Pression et volume", "Charge et champ", "Masse et accélération"), 0, "Science", Difficulty.HARD, explanation = "La constante de Boltzmann (k) établit le lien entre l'énergie cinétique moyenne des particules et la température thermodynamique d'un système. Elle permet de convertir des mesures de température en unités d'énergie."),
        Question(12431, "En chimie, la réaction d'addition se produit sur??", listOf("Les alcanes", "Les alcènes", "Les alcynes", "Les arènes"), 2, "Science", Difficulty.HARD, explanation = "Les alcynes possèdent une triple liaison carbone-carbone, qui peut s'ouvrir pour fixer de nouveaux atomes ou groupes, contrairement aux alcanes saturés."),
        Question(12432, "Le radical libre est une molécule avec??", listOf("Charge positive", "Charge négative", "Électron non apparié", "Proton extra"), 2, "Science", Difficulty.HARD, explanation = "Les radicaux libres possèdent un électron non apparié sur leur couche externe, ce qui les rend très instables et réactifs chimiquement."),
        Question(12433, "La polarisabilité d'une molécule dépend de??", listOf("Sa charge", "Sa taille", "Sa masse", "Son volume"), 1, "Science", Difficulty.HARD, explanation = "Plus une molécule est grande, plus son nuage électronique est volumineux et déformable, ce qui augmente sa polarisabilité."),
        Question(12434, "L'électronégativité augmente en??", listOf("Descendant un groupe", "Montant un groupe", "Descendant une période", "Montant une période"), 1, "Science", Difficulty.HARD, explanation = "Dans le tableau périodique, l'électronégativité augmente de gauche à droite sur une période et de bas en haut dans un groupe, car les atomes attirent plus fortement les électrons."),
        Question(12435, "La durite chimique la plus forte est entre le??", listOf("C et H", "H et F", "N et O", "C et O"), 1, "Science", Difficulty.HARD, explanation = "La liaison hydrogène-fluor (H-F) est la plus forte des liaisons covalentes simples car le fluor est l'élément le plus électronégatif, créant une forte polarité."),
        Question(12436, "La force de van der Waals est la plus faible entre?", listOf("Atomes polaires", "Dipôles permanents", "Atomes apolaires", "Ions"), 2, "Science", Difficulty.HARD, explanation = "La force de van der Waals est une interaction intermoléculaire faible qui se manifeste entre atomes ou molécules apolaires, car elle repose sur des dipôles temporaires induits par les fluctuations électroniques."),
        Question(12437, "Quel scientifique a découvert la fission nucléaire?", listOf("Einstein", "Hahn", "Meitner", "Strassmann"), 1, "Science", Difficulty.HARD, explanation = "Otto Hahn et son assistant Fritz Strassmann ont découvert la fission nucléaire en 1938 en bombardant de l'uranium avec des neutrons, une expérience interprétée théoriquement par Lise Meitner."),
        Question(12438, "La fission nucléaire libère de l'énergie sous forme de??", listOf("Rayons gamma", "Radiation alpha", "Radiation bêta", "Toutes les trois"), 3, "Science", Difficulty.HARD, explanation = "Lors d'une fission nucléaire, la masse manquante est convertie en énergie cinétique des fragments, en rayonnement gamma et en neutrons rapides, soit les trois formes citées."),
        Question(12439, "L'énergie d'un photon dépend de sa??", listOf("Longueur d'onde", "Fréquence", "Vitesse", "Direction"), 1, "Science", Difficulty.HARD, explanation = "L'énergie d'un photon est directement proportionnelle à sa fréquence selon la relation E = h×ν, où h est la constante de Planck."),
        Question(12440, "Le principe d'incertitude d'Heisenberg concerne??", listOf("Position et vitesse", "Position et momentum", "Énergie et temps", "Tous les trois"), 3, "Science", Difficulty.HARD, explanation = "Le principe d'incertitude d'Heisenberg stipule qu'il est impossible de connaître simultanément avec précision certaines paires de grandeurs physiques, comme la position et la quantité de mouvement, l'énergie et le temps, ou encore l'angle et le moment angulaire."),
        Question(12441, "Qui a remporté la bataille de Crécy?", listOf("France", "Angleterre", "Bourgogne", "Flandre"), 1, "Histoire", Difficulty.HARD, explanation = "La bataille de Crécy, en 1346, fut une victoire anglaise décisive pendant la guerre de Cent Ans, marquée par l'utilisation efficace des archers anglais contre la cavalerie française."),
        Question(12442, "La bataille d'Azincourt a eu lieu en??", listOf("1415", "1420", "1429", "1435"), 0, "Histoire", Difficulty.HARD, explanation = "La bataille d'Azincourt, opposant les Anglais d'Henri V aux Français, s'est déroulée le 25 octobre 1415 pendant la guerre de Cent Ans."),
        Question(12443, "Jeanne d'Arc a été brûlée en??", listOf("1429", "1430", "1431", "1435"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Jeanne d'Arc fut exécutée à Rouen le 30 mai 1431, après un procès en hérésie mené par les Anglais durant la guerre de Cent Ans."),
        Question(12444, "Le Siège de Calais a duré environ??", listOf("6 mois", "1 an", "1.5 ans", "2 ans"), 2, "Histoire", Difficulty.HARD, explanation = "Le siège de Calais, mené par Édouard III d'Angleterre pendant la guerre de Cent Ans, a duré de septembre 1346 à août 1347, soit environ 11 mois, ce qui correspond à un an et demi."),
        Question(12445, "La paix de Troyes a été signée en??", listOf("1420", "1425", "1430", "1435"), 0, "Histoire", Difficulty.HARD, explanation = "Le traité de Troyes, signé en 1420, met fin à la guerre de Cent Ans entre la France et l'Angleterre en désignant le roi d'Angleterre Henri V comme héritier du trône de France."),
        Question(12446, "Le traité d'Amiens a été signé en??", listOf("1801", "1802", "1803", "1804"), 1, "Histoire", Difficulty.HARD, explanation = "Le traité d'Amiens, signé le 25 mars 1802, mit fin à la guerre entre la France et le Royaume-Uni, marquant une brève période de paix pendant les guerres napoléoniennes."),
        Question(12447, "Napoléon a abdiqué pour la première fois en??", listOf("1813", "1814", "1815", "1816"), 1, "Histoire", Difficulty.MEDIUM, explanation = "Après la défaite de la campagne de France et la prise de Paris par les coalisés, Napoléon abdique le 6 avril 1814 à Fontainebleau."),
        Question(12448, "Les Cent-Jours ont duré??", listOf("100 jours", "111 jours", "120 jours", "150 jours"), 1, "Histoire", Difficulty.HARD, explanation = "Cette période correspond au retour au pouvoir de Napoléon Ier entre son évasion de l'île d'Elbe (1er mars 1815) et sa seconde abdication après Waterloo (22 juin 1815)."),
        Question(12449, "Waterloo a changé l'histoire de l'Europe en tant que??", listOf("Première défaite", "Fin de l'empire", "Victoire décisive", "Défaite définitive"), 3, "Histoire", Difficulty.HARD, explanation = "La bataille de Waterloo en 1815 marque la défaite définitive de Napoléon Bonaparte, mettant fin à l'Empire français et aux guerres napoléoniennes en Europe."),
        Question(12450, "L'indépendance américaine a été déclarée en??", listOf("1775", "1776", "1777", "1778"), 1, "Histoire", Difficulty.EASY, explanation = "Le 4 juillet 1776, le Congrès continental adopte la Déclaration d'indépendance des États-Unis, rompant officiellement les liens avec la Grande-Bretagne."),
        Question(12451, "La Révolution française a eu lieu en??", listOf("1788", "1789", "1790", "1791"), 1, "Histoire", Difficulty.EASY, explanation = "La Révolution française débute en 1789 avec la convocation des États généraux et la prise de la Bastille le 14 juillet, marquant la fin de l'Ancien Régime."),
        Question(12452, "L'empire colonial français en Afrique était appelé??", listOf("Afrique française", "Français-Afrique", "Afrique-Française", "l'AOF et AEF"), 3, "Histoire", Difficulty.HARD, explanation = "L'empire colonial français en Afrique était organisé en deux fédérations : l'Afrique-Occidentale française (AOF) et l'Afrique-Équatoriale française (AEF), créées pour administrer les territoires conquis."),
        Question(12453, "La Première Guerre mondiale a duré??", listOf("3 ans", "4 ans", "5 ans", "6 ans"), 1, "Histoire", Difficulty.EASY, explanation = "Le conflit a débuté le 28 juillet 1914 et s'est achevé le 11 novembre 1918, soit une durée de quatre ans."),
        Question(12454, "Le Traité de Versailles a imposé à l'Allemagne??", listOf("Réparations", "Restrictions militaires", "Perte de territoires", "Tout ce qui précède"), 3, "Histoire", Difficulty.MEDIUM, explanation = "Le traité de Versailles, signé en 1919, imposait à l'Allemagne des clauses territoriales, militaires, financières et morales, incluant la perte de territoires, la limitation de son armée, des réparations colossales et la reconnaissance de sa responsabilité dans la guerre."),
        Question(12455, "La Grande Dépression a commencé en??", listOf("1927", "1928", "1929", "1930"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Le krach boursier de Wall Street en octobre 1929 a déclenché une crise économique mondiale, marquant le début de la Grande Dépression."),
        Question(12456, "Hitler est arrivé au pouvoir en??", listOf("1931", "1932", "1933", "1934"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Adolf Hitler a été nommé chancelier de l'Allemagne le 30 janvier 1933, marquant son accession légale au pouvoir. Cette nomination a ouvert la voie à la mise en place de la dictature nazie."),
        Question(12457, "L'Holocauste a causé la mort de combien de millions de personnes?", listOf("3", "5", "6", "8"), 2, "Histoire", Difficulty.MEDIUM, explanation = "L'Holocauste désigne le génocide systématique d'environ six millions de Juifs par l'Allemagne nazie entre 1941 et 1945."),
        Question(12458, "La Shoah est un autre nom pour??", listOf("La Première Guerre mondiale", "La Seconde Guerre mondiale", "L'Holocauste", "La Grande Dépression"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Le terme Shoah, d'origine hébraïque, désigne spécifiquement l'extermination systématique des Juifs par l'Allemagne nazie, tandis qu'Holocauste, d'origine grecque, est le terme plus couramment utilisé en français pour le même génocide."),
        Question(12459, "La Guerre froide a commencé après??", listOf("La Première Guerre mondiale", "La Seconde Guerre mondiale", "La crise des missiles", "Le mur de Berlin"), 1, "Histoire", Difficulty.MEDIUM, explanation = "La Guerre froide a débuté après la Seconde Guerre mondiale en raison des tensions idéologiques et géopolitiques entre les États-Unis et l'Union soviétique, qui émergeaient comme les deux superpuissances rivales."),
        Question(12460, "Quel événement a déclenché la Première Guerre mondiale?", listOf("Assassinat de François-Ferdinand", "Invasion de la Belgique", "Déclaration de guerre allemande", "Mobilisation générale"), 0, "Histoire", Difficulty.MEDIUM, explanation = "L'assassinat de l'archiduc François-Ferdinand d'Autriche le 28 juin 1914 à Sarajevo par un nationaliste serbe a provoqué une crise diplomatique qui a déclenché la Première Guerre mondiale."),
        Question(12461, "Quel événement a déclenché la Crise des missiles?", listOf("Construction du mur de Berlin", "Missiles soviétiques à Cuba", "Invasion de la Baie des Cochons", "Révolution cubaine"), 1, "Histoire", Difficulty.HARD, explanation = "En octobre 1962, la découverte par les États-Unis de missiles nucléaires soviétiques installés à Cuba a provoqué une confrontation directe avec l'URSS, menaçant une guerre nucléaire."),
        Question(12462, "La révolution russe a eu lieu en??", listOf("1915", "1916", "1917", "1918"), 2, "Histoire", Difficulty.MEDIUM, explanation = "La révolution russe de 1917 a renversé le régime tsariste, menant à la prise de pouvoir par les bolcheviks en octobre de la même année."),
        Question(12463, "Quel type de gouvernement a mis en place Lénine?", listOf("Démocratie", "Monarchie", "Communisme", "Fascisme"), 2, "Histoire", Difficulty.MEDIUM, explanation = "Lénine a instauré un régime communiste après la révolution d'Octobre 1917, en renversant le gouvernement provisoire et en établissant la dictature du prolétariat."),
        Question(12464, "Le Komintern a été créé pour??", listOf("Promouvoir le communisme", "Défendre la Russie", "Combattre le fascisme", "Étendre l'empire soviétique"), 0, "Histoire", Difficulty.HARD, explanation = "Le Komintern, ou Internationale communiste, a été fondé en 1919 par Lénine pour coordonner les partis communistes du monde entier et diffuser la révolution bolchevique."),
        Question(12465, "Staline a pris le pouvoir après la mort de??", listOf("Lénine", "Trotsky", "Kamenev", "Zinoviev"), 0, "Histoire", Difficulty.HARD, explanation = "Lénine, fondateur de l'URSS, est mort en 1924, ouvrant une lutte de pouvoir remportée par Staline."),
        Question(12466, "Quel continent s'étend le plus vers le sud?", listOf("Afrique", "Amérique du Sud", "Australie", "Asie"), 0, "Géographie", Difficulty.HARD, explanation = "Le point le plus méridional de l'Afrique, le cap des Aiguilles, se situe plus au sud que celui de tout autre continent, y compris l'Amérique du Sud."),
        Question(12467, "Le Cap Horn est le point le plus au sud de??", listOf("L'Amérique du Nord", "L'Amérique du Sud", "L'Afrique", "L'Asie"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Cap Horn est situé à la pointe de l'archipel de la Terre de Feu, marquant l'extrémité sud du continent sud-américain."),
        Question(12468, "Les archipels volcaniques du Pacifique incluent les??", listOf("Hawaï", "Nouvelle-Zélande", "Tonga", "Samoa"), 0, "Géographie", Difficulty.MEDIUM, explanation = "Les îles Hawaï sont un archipel volcanique majeur du Pacifique, formé par un point chaud tectonique."),
        Question(12469, "La ceinture de feu du Pacifique comprend environ combien de volcans actifs?", listOf("200", "400", "600", "800"), 2, "Géographie", Difficulty.HARD, explanation = "La ceinture de feu du Pacifique concentre environ 600 volcans actifs, soit 75 % des volcans émergés de la planète, en raison des mouvements des plaques tectoniques."),
        Question(12470, "L'Île de Sumatra se trouve dans quel pays?", listOf("Malaisie", "Indonésie", "Philippines", "Brunei"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Sumatra est la sixième plus grande île du monde et fait partie de l'archipel indonésien, située à l'ouest de Java et Bornéo."),
        Question(12471, "Le détroit de Lombok sépare quelles deux îles?", listOf("Sumatra et Java", "Bali et Lombok", "Java et Bali", "Lombok et Sumbawa"), 2, "Géographie", Difficulty.HARD, explanation = "Le détroit de Lombok sépare les îles de Java et Bali, situées en Indonésie, et marque la limite entre les écorégions asiatiques et australiennes."),
        Question(12472, "L'Île de Socotra appartient à quel pays?", listOf("Oman", "Yémen", "Arabie Saoudite", "Émirats Arabes Unis"), 1, "Géographie", Difficulty.HARD, explanation = "Socotra est un archipel situé dans l'océan Indien, rattaché au Yémen depuis 1990."),
        Question(12473, "Les îles Nicobar appartiennent à quel pays?", listOf("Thaïlande", "Inde", "Birmanie", "Malaisie"), 1, "Géographie", Difficulty.HARD, explanation = "Les îles Nicobar forment un territoire de l'Union indienne, avec les îles Andaman, sous le nom de îles Andaman-et-Nicobar."),
        Question(12474, "L'Île de Timor est partagée entre l'Indonésie et le??", listOf("Papouasie-Nouvelle-Guinée", "Timor oriental", "Malaisie", "Philippines"), 1, "Géographie", Difficulty.HARD, explanation = "Timor est divisée entre l'Indonésie à l'ouest et le Timor oriental, un État souverain indépendant depuis 2002."),
        Question(12475, "Le Désert de Taklamakan se trouve en??", listOf("Mongolie", "Chine", "Russie", "Kazakhstan"), 1, "Géographie", Difficulty.HARD, explanation = "Le désert de Taklamakan est situé dans la région autonome ouïghoure du Xinjiang, dans le nord-ouest de la Chine. C'est l'un des plus grands déserts de sable au monde."),
        Question(12476, "La rivière Brahmapoutre traverse quel pays?", listOf("Inde uniquement", "Inde et Bangladesh", "Bangladesh uniquement", "Inde, Chine et Bangladesh"), 3, "Géographie", Difficulty.HARD, explanation = "Le Brahmapoutre prend sa source au Tibet (Chine), traverse le nord-est de l'Inde, puis se jette dans le golfe du Bengale au Bangladesh."),
        Question(12477, "Le Lac Tanganyika est le plus profond du continent??", listOf("Asie", "Américain", "Africain", "Européen"), 2, "Géographie", Difficulty.HARD, explanation = "Le Lac Tanganyika, avec une profondeur maximale de 1 470 mètres, est le deuxième lac le plus profond du monde et le plus profond d'Afrique. Il fait partie de la vallée du Grand Rift."),
        Question(12478, "La calotte glaciaire de l'Antarctique contient environ combien de pourcents de la glace mondiale?", listOf("60%", "70%", "80%", "90%"), 3, "Géographie", Difficulty.HARD, explanation = "L'Antarctique renferme environ 90 % de la glace mondiale et 70 % de l'eau douce de la planète, ce qui en fait le plus grand réservoir de glace terrestre."),
        Question(12479, "L'Île du Roi-Guillaume se trouve en??", listOf("Groenland", "Canada", "Russie", "Antarctique"), 1, "Géographie", Difficulty.HARD, explanation = "L'Île du Roi-Guillaume est située dans l'archipel arctique canadien, au Nunavut, dans le nord du Canada."),
        Question(12480, "Le Passage du Nord-Ouest relie l'océan Atlantique au??", listOf("Pacifique", "Indien", "Arctique", "Atlantique"), 0, "Géographie", Difficulty.HARD, explanation = "Le Passage du Nord-Ouest traverse l'archipel arctique canadien, reliant l'océan Atlantique à l'océan Pacifique par le détroit de Béring."),
        Question(12481, "Quel manga iscours sur les pouvoirs psychiques?", listOf("Mob Psycho 100", "Psycho-Pass", "Death Note", "Code Geass"), 0, "Culture", Difficulty.MEDIUM, explanation = "Mob Psycho 100 suit Shigeo Kageyama, un collégien aux puissants pouvoirs psychiques qu'il apprend à maîtriser."),
        Question(12482, "La BD 'Sandman' a été écrite par??", listOf("Alan Moore", "Neil Gaiman", "Frank Miller", "Grant Morrison"), 1, "Culture", Difficulty.HARD, explanation = "Neil Gaiman a créé la série de bande dessinée Sandman pour DC Comics, publiée de 1989 à 1996, qui est devenue un classique du genre fantastique et onirique."),
        Question(12483, "Quel jeu de plateau simule une gestion bancaire?", listOf("Monopoly", "Carcassonne", "Puerto Rico", "Agricola"), 0, "Culture", Difficulty.EASY, explanation = "Le Monopoly est un jeu de société où les joueurs achètent, louent et échangent des propriétés, simulant des transactions financières et une gestion bancaire simplifiée."),
        Question(12484, "Le 'Safran' est une épice très coûteuse originaire de??", listOf("Iran", "Inde", "Maroc", "Espagne"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le safran provient du crocus sativus, et l'Iran est de loin le premier producteur mondial, assurant plus de 90% de la récolte."),
        Question(12485, "Quel anime adapte le manga 'My Hero Academia'?", listOf("Studio A-1 Pictures", "Studio Bones", "MAPPA", "Ufotable"), 1, "Culture", Difficulty.HARD, explanation = "Le studio Bones a produit l'adaptation animée de My Hero Academia, diffusée depuis 2016."),
        Question(12486, "La BD 'V pour Vendetta' a été écrite par??", listOf("Frank Miller", "Alan Moore", "Neil Gaiman", "Grant Morrison"), 1, "Culture", Difficulty.HARD, explanation = "Alan Moore, auteur britannique renommé, a écrit \"V pour Vendetta\" avec le dessinateur David Lloyd, publiée dans les années 1980."),
